const S="https://staging.incusgrid.com",I="https://play.google.com/store/apps/details?id=com.incusgrid.app",e="https://blog.incusgrid.com",P="https://www.instagram.com/incusgrid/",G="https://www.facebook.com/incusgrid/",o={path:"/",htmlLang:"en",ogLocale:"en_GB",meta:{title:"IncusGrid · Plan your sailing season with real data",description:"Sailing routes and boat stays from real passages, plus years of wind, wave and lightning data on one map. Plan your next season.",keywords:"sailing routes, cruising routes, boat stays, anchorage, marina, wintering, wind statistics, sea state, waves, lightning, thunderstorm, terrain shielding, sailing planning, yacht, cruising"},nav:{routes:"Routes",stays:"Boat stays",weather:"Weather",terrain:"Terrain",blog:"Blog",openApp:"Open the map"},hero:{position:"Sailing intelligence",titleA:"Not another weather app.",titleB:"Not another sailing network.",lead:"IncusGrid turns years of data into the local knowledge every crew needs before casting off: real boat movements, wind, waves and lightning on one map — so you can plan your next passage with the collective knowledge of thousands of sailors.",ctaApp:"Open the map",ctaAndroid:"Android app",heroAlt:"Sailing routes across the Caribbean Sea, from Hispaniola to the Lesser Antilles and the coast of South America, drawn from real passages of cruising boats.",heroCaption:"Sailing routes, Caribbean Sea · all months",notes:[{label:"Boats",value:"Thousands"},{label:"Movements",value:"Millions"},{label:"Lightning strikes",value:"Billions"},{label:"Coverage",value:"Worldwide"}]},contrast:{kicker:"Not a forecast",title:"The forecast tells you about tomorrow. IncusGrid tells you about the season.",text:"Which passage do crews take in June? Where do boats spend the winter? Which month brings the Meltemi, and which side of the bay is better shielded from lightning? Answers that only show up when you look at many years at once."},chapters:[{id:"routes",number:"01",kicker:"Sailing routes",title:"Plan crossings on the experience of thousands of crews.",text:"Thousands of real passages show when a crossing makes sense, in which direction, and where crews set off and arrive. The prevailing winds, good places to wait for a weather window and a safe landfall after a night at sea are already built in. From Sicily to the Ionian Islands, for example, most boats head east in May and June and sail back in September.",points:["Popularity per month and direction","The most popular routes in your current map view","Share a route with your crew"],image:"route-detail",alt:"The route from Sicily to the Ionian Islands selected, with how popular it is in each month and direction.",coords:"38°12′N · 017°30′E",caption:"Sicily → Ionian Islands, by month and direction"},{id:"route-wind",number:"02",kicker:"Wind along the route",title:"Know the wind before you cast off.",text:"Every route shows the wind you can expect on it, month by month: where it comes from, how strong it blows, how much of the passage you sail upwind, on a beam reach or downwind, and how often the sea stays calm. From Sicily to the Ionian Islands in May: wind from the northwest, Bft 3, more than half of the way downwind.",points:["Prevailing wind and Beaufort force for every month","Upwind, beam reach or downwind on the route’s course","Sea state along the route"],image:"route-wind",alt:"The route card for Sicily to the Ionian Islands: prevailing wind, Beaufort force, wind strength, point of sail and sea state for every month, with May selected.",coords:"",caption:"Sicily → Ionian Islands, wind in May",card:!0},{id:"stays",number:"03",kicker:"Boat stays",title:"Where other boats stay.",text:"Where do crews leave their boat for two months in summer, and where do they spend the winter? Boat stays show the harbours and anchorages where boats paused — from a few days to more than six months, by season.",points:["Filter by length of stay","See in which months boats stay at a place","Spot popular wintering harbours"],image:"stay-detail",alt:"Preveza: typical length of stay and the months in which boats stay there.",coords:"38°57′N · 020°45′E",caption:"Preveza, length of stay and season"},{id:"hotspots",number:"04",kicker:"Hotspots",title:"Find the quieter anchorage.",text:"Where do boats crowd in August, and where is there still room? Hotspots shows how busy each sailing area is, month by month. The Ionian and the Saronic Gulf glow, while Andros, a day’s sail from Athens, stays calm.",points:["From quiet to crowded","Every month of the year","Busiest and quietest months at any point"],image:"hotspots",alt:"How busy Greek sailing areas are in August: crowded around the Ionian Islands and the Saronic Gulf, quiet off Andros, with the point inspector open.",coords:"38°24′N · 023°36′E",caption:"Hotspots, Greece, August"},{id:"wind",number:"05",kicker:"Wind",title:"How much northerly wind should you expect?",text:"Pick a direction and a month: in July the central Aegean turns deep blue. That’s the Meltemi. Tap a spot near Mykonos and you see it blow from the north in 60% of all July hours or more.",points:["Strength and direction for every month","Wind by time of day","Tap any point for its numbers"],image:"wind",alt:"How often the wind blows from the north in the Aegean Sea in July, with the point inspector open near Mykonos.",coords:"37°36′N · 025°00′E",caption:"Wind from the north, Aegean Sea, July"},{id:"waves",number:"06",kicker:"Waves",title:"Know the sea state before you go.",text:"How many days per month bring waves of 2.5 m or more? In January the reach of the Mistral across the Gulf of Lion stands out clearly.",points:["From calm to very rough seas","Swell and short, steep seas","Every month of the year"],image:"waves",alt:"Days with rough seas in the western Mediterranean in January.",coords:"41°00′N · 005°00′E",caption:"Rough days, western Mediterranean, January"},{id:"potential",number:"07",kicker:"Thunderstorm Potential",title:"Where thunderstorms can build.",text:"The share of time with thunderstorm-favourable conditions, month by month — including places where storms could build even on days when none formed.",points:["Every month of the year","Tap any point for its numbers"],image:"potential",alt:"Thunderstorm Potential around Panama in September.",coords:"09°00′N · 079°30′W",caption:"Thunderstorm Potential, Panama, September"},{id:"terrain",number:"08",kicker:"Terrain Exposure",title:"Same bay, different shielding.",text:"Surrounding hills can shield an anchorage from lightning. Terrain Exposure shows how well the terrain protects each part of a bay, so you can pick the better side before you drop anchor.",points:["Compare spots within one bay","Combine it with historical thunderstorm days"],image:"terrain",alt:"Terrain Exposure in Komiža Bay on Vis, Croatia.",coords:"43°02′N · 016°05′E",caption:"Komiža Bay, Vis",markers:[{x:56.9,y:57.69,text:"Little shielding from surrounding terrain.",color:"#762a83"},{x:53.84,y:26.35,text:"Some shielding from surrounding terrain.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Stronger shielding from surrounding terrain.",color:"#5aae61"}]}],story:{kicker:"Our story",title:"Born from a close call.",text:"In October 2024, our family was sailing the Ionian Sea when lightning struck right next to our boat. That moment raised a simple question: are we safer here, or on the other side of the bay? IncusGrid started as the answer — and grew into a map of everything we wished we had known before that season.",more:"Read the full story",link:`${e}/blog/introducing-incusgrid/`,place:"Igoumenitsa, Greece",note:"Where the idea was born"},fromBlog:{kicker:"From the blog",title:"Data stories from the water.",all:"All posts",note:""},devices:{kicker:"Web & Android",title:"On deck or at the chart table.",text:"Use IncusGrid in any browser or install the Android app. Search for your sailing area and explore on phone, tablet or laptop.",points:["No installation needed in the browser","Android app on Google Play","Available in 19 languages"],web:"Open in the browser",android:"Get it on Google Play",phoneAlt:"IncusGrid Android app showing boat stays around the Ionian Islands."},final:{title:"Plan your next season.",text:"Routes, boat stays, wind, waves and lightning — one map, built from many years of real data.",cta:"Open the map"},disclaimerLabel:"Caution",disclaimer:"IncusGrid shows historical patterns for planning. It is not a weather forecast or a navigation aid. Routes are drawn schematically, and boat stays are derived from pauses in boat reports, not confirmed berths. Always check current forecasts, official charts and local conditions before you go to sea.",footer:{blog:"Blog",legal:"Legal Notice",privacy:"Privacy Policy",terms:"Terms of Service",cookies:"Cookie Settings",support:"Support",madeWith:"Made with",made:"in Portugal",englishOnly:""}},s={path:"/de",htmlLang:"de",ogLocale:"de_DE",meta:{title:"IncusGrid · Plane deine Segelsaison mit echten Daten",description:"Segelrouten und Bootspausen aus echten Passagen, dazu Jahre an Wind-, Wellen- und Blitzdaten auf einer Karte. Plane deine nächste Saison.",keywords:"Segelrouten, Törnplanung, Ankerplatz, Marina, Winterlager, Windstatistik, Seegang, Wellen, Blitze, Gewitter, Segeln, Yacht, Blauwassersegeln"},nav:{routes:"Routen",stays:"Bootspausen",weather:"Wetter",terrain:"Gelände",blog:"Blog",openApp:"Karte öffnen"},hero:{position:"Sailing intelligence",titleA:"Keine weitere Wetter-App.",titleB:"Kein weiteres Segler-Netzwerk.",lead:"IncusGrid macht aus Jahren an Daten das Revierwissen, das jede Crew vor dem Ablegen braucht: echte Bootsbewegungen, Wind, Wellen und Blitze auf einer Karte — damit du deine nächste Passage mit dem gesammelten Wissen tausender Segler planst.",ctaApp:"Karte öffnen",ctaAndroid:"Android-App",heroAlt:"Segelrouten in der Karibik, von Hispaniola über die Kleinen Antillen bis zur Küste Südamerikas, gezeichnet aus echten Passagen von Fahrtenyachten.",heroCaption:"Segelrouten, Karibisches Meer · alle Monate",notes:[{label:"Boote",value:"Tausende"},{label:"Bewegungen",value:"Millionen"},{label:"Blitzeinschläge",value:"Milliarden"},{label:"Abdeckung",value:"Weltweit"}]},contrast:{kicker:"Keine Vorhersage",title:"Die Vorhersage sagt dir, was morgen kommt. IncusGrid zeigt dir die Saison.",text:"Welche Passage nehmen Crews im Juni? Wo überwintern Boote? Welcher Monat bringt den Meltemi, und welche Seite der Bucht ist besser vor Blitzen geschützt? Antworten, die erst sichtbar werden, wenn man viele Jahre auf einmal betrachtet."},chapters:[{id:"routes",number:"01",kicker:"Segelrouten",title:"Plane Überfahrten mit der Erfahrung tausender Crews.",text:"Tausende echte Passagen zeigen, wann eine Überfahrt sinnvoll ist, in welche Richtung, und wo Crews ablegen und ankommen. Die vorherrschenden Winde, gute Orte, um auf ein Wetterfenster zu warten, und ein sicherer Landfall nach einer Nacht auf See stecken schon darin. Von Sizilien zu den Ionischen Inseln zum Beispiel fahren die meisten Boote im Mai und Juni nach Osten und im September zurück.",points:["Beliebtheit je Monat und Richtung","Die beliebtesten Routen im aktuellen Kartenausschnitt","Teile eine Route mit deiner Crew"],image:"route-detail",alt:"Die Route von Sizilien zu den Ionischen Inseln ausgewählt, mit ihrer Beliebtheit je Monat und Richtung.",coords:"38°12′N · 017°30′E",caption:"Sizilien → Ionische Inseln, nach Monat und Richtung"},{id:"route-wind",number:"02",kicker:"Wind entlang der Route",title:"Kenne den Wind, bevor du ablegst.",text:"Jede Route zeigt den Wind, den du dort erwarten kannst, Monat für Monat: woher er kommt, wie stark er weht, wie viel der Passage du am Wind, mit halbem Wind oder raumschots segelst und wie oft die See ruhig bleibt. Von Sizilien zu den Ionischen Inseln im Mai: Wind aus Nordwest, 3 Bft, mehr als die Hälfte des Weges raumschots.",points:["Vorherrschender Wind und Windstärke in Beaufort für jeden Monat","Am Wind, halber Wind oder raumschots auf dem Kurs der Route","Seegang entlang der Route"],image:"route-wind",alt:"Die Routenkarte von Sizilien zu den Ionischen Inseln: vorherrschender Wind, Windstärke in Beaufort, Stärke, Kurs und Seegang für jeden Monat, mit ausgewähltem Mai.",coords:"",caption:"Sizilien → Ionische Inseln, Wind im Mai",card:!0},{id:"stays",number:"03",kicker:"Bootspausen",title:"Wo andere Boote liegen.",text:"Wo lassen Crews ihr Boot im Sommer für zwei Monate liegen, und wo verbringen sie den Winter? Bootspausen zeigen die Häfen und Ankerplätze, an denen Boote pausiert haben — von wenigen Tagen bis zu mehr als sechs Monaten, nach Saison.",points:["Nach Liegedauer filtern","Sehen, in welchen Monaten Boote an einem Ort liegen","Beliebte Winterhäfen entdecken"],image:"stay-detail",alt:"Preveza: typische Liegedauer und die Monate, in denen Boote dort liegen.",coords:"38°57′N · 020°45′E",caption:"Preveza, Liegedauer und Saison"},{id:"hotspots",number:"04",kicker:"Hotspots",title:"Das ruhigere Plätzchen finden.",text:"Wo drängen sich im August die Boote, und wo ist noch Platz? Hotspots zeigt Monat für Monat, wie belebt ein Revier ist. Ionisches Meer und Saronischer Golf leuchten, Andros dagegen, eine Tagesetappe von Athen entfernt, bleibt ruhig.",points:["Von ruhig bis überlaufen","Jeder Monat des Jahres","Belebteste und ruhigste Monate an jedem Punkt"],image:"hotspots",alt:"Wie belebt die griechischen Reviere im August sind: voll um die Ionischen Inseln und im Saronischen Golf, ruhig vor Andros, mit geöffnetem Ortsinspektor.",coords:"38°24′N · 023°36′E",caption:"Hotspots, Griechenland, August"},{id:"wind",number:"05",kicker:"Wind",title:"Wie viel Nordwind erwartet dich?",text:"Wähle Richtung und Monat: Im Juli färbt sich die zentrale Ägäis tiefblau. Das ist der Meltemi. Tippe auf einen Punkt bei Mykonos, und du siehst: Im Juli kommt der Wind in 60 % aller Stunden oder mehr aus Norden.",points:["Stärke und Richtung für jeden Monat","Wind nach Tageszeit","Tippe auf einen Punkt für seine Werte"],image:"wind",alt:"Wie oft der Wind im Juli in der Ägäis aus Norden weht, mit geöffnetem Punkt-Inspektor bei Mykonos.",coords:"37°36′N · 025°00′E",caption:"Wind aus Norden, Ägäis, Juli"},{id:"waves",number:"06",kicker:"Wellen",title:"Kenne den Seegang, bevor du losfährst.",text:"Wie viele Tage im Monat bringen Wellen ab 2,5 m? Im Januar sieht man deutlich, wie weit der Mistral über den Golfe du Lion hinausreicht.",points:["Von ruhiger bis sehr rauer See","Dünung und kurze, steile See","Jeder Monat des Jahres"],image:"waves",alt:"Tage mit rauer See im westlichen Mittelmeer im Januar.",coords:"41°00′N · 005°00′E",caption:"Raue Tage, westliches Mittelmeer, Januar"},{id:"potential",number:"07",kicker:"Gewitterpotenzial",title:"Wo sich Gewitter bilden können.",text:"Der Zeitanteil mit gewitterbegünstigenden Bedingungen, Monat für Monat — auch dort, wo sich Gewitter hätten bilden können, an Tagen, an denen keines entstand.",points:["Jeder Monat des Jahres","Tippe auf einen Punkt für seine Werte"],image:"potential",alt:"Gewitterpotenzial rund um Panama im September.",coords:"09°00′N · 079°30′W",caption:"Gewitterpotenzial, Panama, September"},{id:"terrain",number:"08",kicker:"Geländeexposition",title:"Gleiche Bucht, andere Abschirmung.",text:"Umliegende Hügel können einen Ankerplatz vor Blitzen abschirmen. Die Geländeexposition zeigt, wie gut das Gelände jeden Teil einer Bucht schützt — damit du die bessere Seite wählst, bevor der Anker fällt.",points:["Vergleiche Stellen innerhalb einer Bucht","Kombiniere sie mit den historischen Gewittertagen"],image:"terrain",alt:"Geländeexposition in der Bucht von Komiža auf Vis, Kroatien.",coords:"43°02′N · 016°05′E",caption:"Bucht von Komiža, Vis",markers:[{x:56.9,y:57.69,text:"Geringe Abschirmung durch das umliegende Gelände.",color:"#762a83"},{x:53.84,y:26.35,text:"Etwas Abschirmung durch das umliegende Gelände.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Stärkere Abschirmung durch das umliegende Gelände.",color:"#5aae61"}]}],story:{kicker:"Unsere Geschichte",title:"Entstanden aus einem Schreckmoment.",text:"Im Oktober 2024 war unsere Familie im Ionischen Meer unterwegs, als direkt neben unserem Boot ein Blitz einschlug. Danach stand eine einfache Frage im Raum: Sind wir hier sicherer oder auf der anderen Seite der Bucht? IncusGrid begann als Antwort darauf — und wurde zu einer Karte mit allem, was wir vor dieser Saison gern gewusst hätten.",more:"Die ganze Geschichte lesen (Englisch)",link:`${e}/blog/introducing-incusgrid/`,place:"Igoumenitsa, Griechenland",note:"Wo die Idee entstand"},fromBlog:{kicker:"Aus dem Blog",title:"Datengeschichten vom Wasser.",all:"Alle Beiträge",note:"Beiträge auf Englisch."},devices:{kicker:"Web & Android",title:"An Deck oder am Kartentisch.",text:"Nutze IncusGrid in jedem Browser oder installiere die Android-App. Suche dein Revier und erkunde es auf Handy, Tablet oder Laptop.",points:["Im Browser ohne Installation","Android-App bei Google Play","In 19 Sprachen verfügbar"],web:"Im Browser öffnen",android:"Bei Google Play laden",phoneAlt:"IncusGrid-Android-App mit Bootspausen rund um die Ionischen Inseln."},final:{title:"Plane deine nächste Saison.",text:"Routen, Bootspausen, Wind, Wellen und Blitze — eine Karte, gebaut aus vielen Jahren echter Daten.",cta:"Karte öffnen"},disclaimerLabel:"Hinweis",disclaimer:"IncusGrid zeigt historische Muster für die Planung. Es ist keine Wettervorhersage und keine Navigationshilfe. Routen sind schematisch gezeichnet, und Bootspausen werden aus Pausen in Bootsmeldungen abgeleitet, nicht aus bestätigten Liegeplätzen. Prüfe vor dem Auslaufen immer aktuelle Vorhersagen, amtliche Seekarten und die Bedingungen vor Ort.",footer:{blog:"Blog",legal:"Impressum",privacy:"Datenschutz",terms:"Nutzungsbedingungen",cookies:"Cookie-Einstellungen",support:"Support",madeWith:"Mit",made:"gemacht in Portugal",englishOnly:"Rechtliche Seiten auf Englisch."}},l={path:"/fr",htmlLang:"fr",ogLocale:"fr_FR",meta:{title:"IncusGrid · Votre saison de voile, avec des données réelles",description:"Routes de navigation et pauses de bateaux issues de vraies traversées, plus des années de vent, de vagues et de foudre sur une carte. Préparez votre saison.",keywords:"routes de navigation, navigation hauturière, croisière à la voile, mouillage, port, hivernage, statistiques de vent, état de la mer, vagues, houle, foudre, orages, préparer une navigation, voilier, grand voyage"},nav:{routes:"Routes",stays:"Pauses des bateaux",weather:"Météo",terrain:"Relief",blog:"Blog",openApp:"Ouvrir la carte"},hero:{position:"Sailing intelligence",titleA:"Pas une énième appli météo.",titleB:"Pas un énième réseau de navigateurs.",lead:"IncusGrid transforme des années de données en connaissance locale dont chaque équipage a besoin avant de larguer les amarres : de vrais mouvements de bateaux, le vent, les vagues et la foudre sur une seule carte — pour préparer votre prochaine traversée avec le savoir collectif de milliers de navigateurs.",ctaApp:"Ouvrir la carte",ctaAndroid:"Appli Android",heroAlt:"Routes de navigation à travers la mer des Caraïbes, d’Hispaniola aux Petites Antilles et jusqu’à la côte de l’Amérique du Sud, tracées à partir de vraies traversées de voiliers de croisière.",heroCaption:"Routes de navigation, mer des Caraïbes · tous les mois",notes:[{label:"Bateaux",value:"Des milliers"},{label:"Mouvements",value:"Des millions"},{label:"Impacts de foudre",value:"Des milliards"},{label:"Couverture",value:"Mondiale"}]},contrast:{kicker:"Pas une prévision",title:"La prévision vous parle de demain. IncusGrid vous parle de la saison.",text:"Quelle traversée les équipages font-ils en juin ? Où les bateaux passent-ils l’hiver ? Quel mois amène le meltem, et quel côté de la baie est le mieux protégé de la foudre ? Des réponses qui n’apparaissent qu’en regardant de nombreuses années à la fois."},chapters:[{id:"routes",number:"01",kicker:"Routes de navigation",title:"Planifiez vos traversées avec l’expérience de milliers d’équipages.",text:"Des milliers de vraies traversées montrent quand une traversée a du sens, dans quel sens, et d’où les équipages partent et où ils arrivent. Les vents dominants, les bons endroits pour attendre une fenêtre météo et un atterrissage sûr après une nuit en mer y sont déjà intégrés. De la Sicile aux îles Ioniennes, par exemple, la plupart des bateaux font route vers l’est en mai et juin et reviennent en septembre.",points:["Popularité par mois et par sens","Les routes les plus populaires dans votre vue actuelle de la carte","Partagez une route avec votre équipage"],image:"route-detail",alt:"La route de la Sicile aux îles Ioniennes sélectionnée, avec sa popularité pour chaque mois et chaque sens.",coords:"38°12′N · 017°30′E",caption:"Sicile → îles Ioniennes, par mois et par sens"},{id:"route-wind",number:"02",kicker:"Le vent sur la route",title:"Connaissez le vent avant de larguer les amarres.",text:"Chaque route indique le vent à prévoir, mois par mois : d’où il vient, quelle est sa force, quelle part du trajet se fait au près, au travers ou au portant, et à quelle fréquence la mer reste calme. De la Sicile aux îles Ioniennes en mai : vent de nord-ouest, force 3 Beaufort, plus de la moitié du trajet au portant.",points:["Vent dominant et force Beaufort pour chaque mois","Au près, au travers ou au portant sur le cap de la route","État de la mer le long de la route"],image:"route-wind",alt:"La fiche de la route de la Sicile aux îles Ioniennes : vent dominant, force Beaufort, force du vent, allure et état de la mer pour chaque mois, mai sélectionné.",coords:"",caption:"Sicile → îles Ioniennes, le vent en mai",card:!0},{id:"stays",number:"03",kicker:"Pauses des bateaux",title:"Là où les autres bateaux s’arrêtent.",text:"Où les équipages laissent-ils leur bateau deux mois en été, et où passent-ils l’hiver ? Les pauses des bateaux montrent les ports et les mouillages où des bateaux ont fait halte — de quelques jours à plus de six mois, selon la saison.",points:["Filtrez par durée de pause","Voyez au cours de quels mois les bateaux restent à un endroit","Repérez les ports d’hivernage prisés"],image:"stay-detail",alt:"Preveza : durée de pause typique et mois pendant lesquels les bateaux y restent.",coords:"38°57′N · 020°45′E",caption:"Preveza, durée de pause et saison"},{id:"hotspots",number:"04",kicker:"Hotspots",title:"Trouvez le mouillage plus tranquille.",text:"Où les bateaux se pressent-ils en août, et où reste-t-il de la place ? Hotspots montre, mois par mois, la fréquentation de chaque zone de navigation. La mer Ionienne et le golfe Saronique s’illuminent, tandis qu’Andros, à une journée de navigation d’Athènes, reste calme.",points:["Du calme à la foule","Chaque mois de l’année","Mois les plus fréquentés et les plus calmes en tout point"],image:"hotspots",alt:"La fréquentation des zones de navigation grecques en août : animée autour des îles Ioniennes et dans le golfe Saronique, calme au large d’Andros, avec l’inspecteur de point ouvert.",coords:"38°24′N · 023°36′E",caption:"Hotspots, Grèce, août"},{id:"wind",number:"05",kicker:"Vent",title:"Combien de vent du nord faut-il attendre ?",text:"Choisissez une direction et un mois : en juillet, le centre de la mer Égée vire au bleu profond. C’est le meltem. Touchez un point près de Mykonos et vous voyez qu’il souffle du nord pendant 60 % des heures de juillet, voire plus.",points:["Force et direction pour chaque mois","Le vent selon l’heure","Touchez un point pour voir ses chiffres"],image:"wind",alt:"Fréquence du vent du nord en mer Égée en juillet, avec l’inspecteur de point ouvert près de Mykonos.",coords:"37°36′N · 025°00′E",caption:"Vent du nord, mer Égée, juillet"},{id:"waves",number:"06",kicker:"Vagues",title:"Connaissez l’état de la mer avant de partir.",text:"Combien de jours par mois apportent des vagues de 2,5 m ou plus ? En janvier, la portée du mistral sur le golfe du Lion ressort nettement.",points:["De la mer calme à la mer très agitée","Houle et mer courte et creuse","Chaque mois de l’année"],image:"waves",alt:"Jours de mer agitée en Méditerranée occidentale en janvier.",coords:"41°00′N · 005°00′E",caption:"Jours agités, Méditerranée occidentale, janvier"},{id:"potential",number:"07",kicker:"Potentiel orageux",title:"Là où les orages peuvent se former.",text:"La part du temps avec des conditions favorables aux orages, mois par mois — y compris là où des orages auraient pu se former, les jours où il n’y en a pas eu.",points:["Chaque mois de l’année","Touchez un point pour voir ses chiffres"],image:"potential",alt:"Potentiel orageux autour du Panama en septembre.",coords:"09°00′N · 079°30′W",caption:"Potentiel orageux, Panama, septembre"},{id:"terrain",number:"08",kicker:"Exposition du terrain",title:"Même baie, autre protection.",text:"Les collines alentour peuvent protéger un mouillage de la foudre. L’exposition du terrain montre à quel point le relief protège chaque partie d’une baie, pour que vous choisissiez le meilleur côté avant de jeter l’ancre.",points:["Comparez les endroits d’une même baie","Combinez-la avec les jours d’orage historiques"],image:"terrain",alt:"Exposition du terrain dans la baie de Komiža, sur l’île de Vis, en Croatie.",coords:"43°02′N · 016°05′E",caption:"Baie de Komiža, Vis",markers:[{x:56.9,y:57.69,text:"Faible effet protecteur du relief environnant.",color:"#762a83"},{x:53.84,y:26.35,text:"Effet protecteur partiel du relief environnant.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Effet protecteur plus marqué du relief environnant.",color:"#5aae61"}]}],story:{kicker:"Notre histoire",title:"Né d’une grosse frayeur.",text:"En octobre 2024, notre famille naviguait en mer Ionienne quand la foudre est tombée juste à côté de notre bateau. Ce moment a soulevé une question simple : sommes-nous plus en sécurité ici, ou de l’autre côté de la baie ? IncusGrid est né pour y répondre — et est devenu une carte de tout ce que nous aurions aimé savoir avant cette saison.",more:"Lire toute l’histoire (en anglais)",link:`${e}/blog/introducing-incusgrid/`,place:"Igoumenitsa, Grèce",note:"Là où l’idée est née"},fromBlog:{kicker:"Sur le blog",title:"Des histoires de données, côté mer.",all:"Tous les articles",note:"Articles en anglais."},devices:{kicker:"Web & Android",title:"Sur le pont ou à la table à cartes.",text:"Utilisez IncusGrid dans n’importe quel navigateur ou installez l’appli Android. Cherchez votre bassin de navigation et explorez-le sur téléphone, tablette ou ordinateur portable.",points:["Aucune installation dans le navigateur","Appli Android sur Google Play","Disponible en 19 langues"],web:"Ouvrir dans le navigateur",android:"Disponible sur Google Play",phoneAlt:"L’appli Android IncusGrid affichant les pauses des bateaux autour des îles Ioniennes."},final:{title:"Préparez votre prochaine saison.",text:"Routes, pauses des bateaux, vent, vagues et foudre — une seule carte, construite à partir de nombreuses années de données réelles.",cta:"Ouvrir la carte"},disclaimerLabel:"Attention",disclaimer:"IncusGrid montre des tendances historiques pour préparer vos navigations. Ce n’est ni une prévision météo ni une aide à la navigation. Les routes sont tracées de façon schématique, et les pauses des bateaux sont déduites d’interruptions dans les signalements de position, pas de places de port confirmées. Consultez toujours les prévisions actuelles, les cartes marines officielles et les conditions locales avant de prendre la mer.",footer:{blog:"Blog",legal:"Mentions légales",privacy:"Politique de confidentialité",terms:"Conditions d’utilisation",cookies:"Paramètres des cookies",support:"Assistance",madeWith:"Fait avec",made:"au Portugal",englishOnly:"Pages juridiques en anglais."}},d={path:"/it",htmlLang:"it",ogLocale:"it_IT",meta:{title:"IncusGrid · Pianifica la stagione a vela con dati reali",description:"Rotte a vela e soste delle barche da vere traversate, più anni di dati su vento, onde e fulmini su un’unica mappa. Pianifica la tua prossima stagione.",keywords:"rotte a vela, rotte di crociera, navigazione d’altura, ancoraggio, rada, marina, porto, rimessaggio invernale, statistiche del vento, stato del mare, onde, fulmini, temporali, pianificare una crociera, barca a vela, vela d’altura"},nav:{routes:"Rotte",stays:"Soste delle barche",weather:"Meteo",terrain:"Terreno",blog:"Blog",openApp:"Apri la mappa"},hero:{position:"Sailing intelligence",titleA:"Non l’ennesima app meteo.",titleB:"Non l’ennesimo social per velisti.",lead:"IncusGrid trasforma anni di dati nella conoscenza locale che ogni equipaggio deve avere prima di mollare gli ormeggi: veri movimenti di barche, vento, onde e fulmini su un’unica mappa — così pianifichi la tua prossima traversata con il sapere collettivo di migliaia di velisti.",ctaApp:"Apri la mappa",ctaAndroid:"App Android",heroAlt:"Rotte a vela nel Mar dei Caraibi, da Hispaniola alle Piccole Antille fino alla costa del Sud America, tracciate da vere traversate di barche da crociera.",heroCaption:"Rotte a vela, Mar dei Caraibi · tutti i mesi",notes:[{label:"Barche",value:"Migliaia"},{label:"Movimenti",value:"Milioni"},{label:"Fulmini",value:"Miliardi"},{label:"Copertura",value:"Mondiale"}]},contrast:{kicker:"Non una previsione",title:"La previsione ti dice com’è domani. IncusGrid ti racconta la stagione.",text:"Quale traversata fanno gli equipaggi a giugno? Dove passano l’inverno le barche? Quale mese porta il Meltemi, e quale lato della baia è più riparato dai fulmini? Risposte che emergono solo guardando molti anni insieme."},chapters:[{id:"routes",number:"01",kicker:"Rotte a vela",title:"Pianifica le traversate con l’esperienza di migliaia di equipaggi.",text:"Migliaia di vere traversate mostrano quando conviene attraversare, in quale direzione, e da dove gli equipaggi partono e dove arrivano. I venti dominanti, i posti giusti per aspettare una finestra meteo e un atterraggio sicuro dopo una notte in mare sono già compresi. Dalla Sicilia alle Isole Ionie, per esempio, la maggior parte delle barche va verso est a maggio e giugno e torna a settembre.",points:["Popolarità per mese e direzione","Le rotte più popolari nella vista attuale della mappa","Condividi una rotta con il tuo equipaggio"],image:"route-detail",alt:"La rotta dalla Sicilia alle Isole Ionie selezionata, con la sua popolarità per ogni mese e direzione.",coords:"38°12′N · 017°30′E",caption:"Sicilia → Isole Ionie, per mese e direzione"},{id:"route-wind",number:"02",kicker:"Il vento lungo la rotta",title:"Conosci il vento prima di mollare gli ormeggi.",text:"Ogni rotta mostra il vento che puoi aspettarti, mese per mese: da dove arriva, quanto soffia forte, quanta parte della traversata navighi di bolina, al traverso o in andatura portante, e quanto spesso il mare resta calmo. Dalla Sicilia alle Isole Ionie a maggio: vento da nord-ovest, forza 3 Beaufort, più di metà del percorso in andatura portante.",points:["Vento dominante e forza Beaufort per ogni mese","Bolina, traverso o andatura portante lungo la rotta","Stato del mare lungo la rotta"],image:"route-wind",alt:"La scheda della rotta dalla Sicilia alle Isole Ionie: vento dominante, forza Beaufort, forza del vento, andatura e stato del mare per ogni mese, con maggio selezionato.",coords:"",caption:"Sicilia → Isole Ionie, il vento a maggio",card:!0},{id:"stays",number:"03",kicker:"Soste delle barche",title:"Dove si fermano le altre barche.",text:"Dove lasciano la barca gli equipaggi per due mesi d’estate, e dove passano l’inverno? Le soste delle barche mostrano i porti e gli ancoraggi in cui le barche si sono fermate — da pochi giorni a più di sei mesi, stagione per stagione.",points:["Filtra per durata della sosta","Scopri in quali mesi le barche restano in un posto","Individua i porti più scelti per l’inverno"],image:"stay-detail",alt:"Preveza: durata tipica della sosta e mesi in cui le barche ci restano.",coords:"38°57′N · 020°45′E",caption:"Preveza, durata della sosta e stagione"},{id:"hotspots",number:"04",kicker:"Hotspot",title:"Trova l’ancoraggio più tranquillo.",text:"Dove si affollano le barche ad agosto, e dove c’è ancora spazio? Hotspot mostra mese per mese quanto è frequentata ogni zona di navigazione. Lo Ionio e il Golfo Saronico si accendono, mentre Andros, a una giornata di navigazione da Atene, resta tranquilla.",points:["Da tranquillo ad affollato","Ogni mese dell’anno","Mesi più e meno frequentati in ogni punto"],image:"hotspots",alt:"Quanto sono frequentate le zone di navigazione greche ad agosto: affollate intorno alle Isole Ionie e nel Golfo Saronico, tranquille al largo di Andros, con l’ispettore del punto aperto.",coords:"38°24′N · 023°36′E",caption:"Hotspot, Grecia, agosto"},{id:"wind",number:"05",kicker:"Vento",title:"Quanto vento da nord devi aspettarti?",text:"Scegli una direzione e un mese: a luglio l’Egeo centrale si tinge di blu intenso. È il Meltemi. Tocca un punto vicino a Mykonos e vedi che soffia da nord per il 60% o più di tutte le ore di luglio.",points:["Intensità e direzione per ogni mese","Vento per fascia oraria","Tocca un punto per vederne i numeri"],image:"wind",alt:"Quanto spesso il vento soffia da nord nel Mar Egeo a luglio, con l’ispettore del punto aperto vicino a Mykonos.",coords:"37°36′N · 025°00′E",caption:"Vento da nord, Mar Egeo, luglio"},{id:"waves",number:"06",kicker:"Onde",title:"Conosci lo stato del mare prima di partire.",text:"Quanti giorni al mese portano onde di 2,5 m o più? A gennaio si vede chiaramente fin dove arriva il Maestrale nel Golfo del Leone.",points:["Dal mare calmo al mare molto agitato","Onda lunga e mare corto e ripido","Ogni mese dell’anno"],image:"waves",alt:"Giorni di mare agitato nel Mediterraneo occidentale a gennaio.",coords:"41°00′N · 005°00′E",caption:"Giorni agitati, Mediterraneo occidentale, gennaio"},{id:"potential",number:"07",kicker:"Potenziale temporalesco",title:"Dove possono formarsi i temporali.",text:"La quota di tempo con condizioni favorevoli ai temporali, mese per mese — anche dove i temporali avrebbero potuto formarsi nei giorni in cui non se n’è formato nessuno.",points:["Ogni mese dell’anno","Tocca un punto per vederne i numeri"],image:"potential",alt:"Potenziale temporalesco intorno a Panama a settembre.",coords:"09°00′N · 079°30′W",caption:"Potenziale temporalesco, Panama, settembre"},{id:"terrain",number:"08",kicker:"Esposizione del terreno",title:"Stessa baia, schermatura diversa.",text:"Le colline intorno possono schermare un ancoraggio dai fulmini. L’Esposizione del terreno mostra quanto il terreno protegge ogni parte di una baia, così scegli il lato migliore prima di dare fondo.",points:["Confronta punti diversi della stessa baia","Combinala con i giorni di temporale storici"],image:"terrain",alt:"Esposizione del terreno nella baia di Komiža, sull’isola di Vis, in Croazia.",coords:"43°02′N · 016°05′E",caption:"Baia di Komiža, Vis",markers:[{x:56.9,y:57.69,text:"Scarsa schermatura del terreno circostante.",color:"#762a83"},{x:53.84,y:26.35,text:"Una certa schermatura del terreno circostante.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Maggiore schermatura del terreno circostante.",color:"#5aae61"}]}],story:{kicker:"La nostra storia",title:"Nato da un grande spavento.",text:"Nell’ottobre 2024 la nostra famiglia navigava nel Mar Ionio quando un fulmine è caduto proprio accanto alla nostra barca. Da quel momento è nata una domanda semplice: siamo più al sicuro qui o dall’altra parte della baia? IncusGrid è nato come risposta — ed è diventato una mappa di tutto ciò che avremmo voluto sapere prima di quella stagione.",more:"Leggi tutta la storia (in inglese)",link:`${e}/blog/introducing-incusgrid/`,place:"Igoumenitsa, Grecia",note:"Dove è nata l’idea"},fromBlog:{kicker:"Dal blog",title:"Storie di dati dal mare.",all:"Tutti gli articoli",note:"Articoli in inglese."},devices:{kicker:"Web & Android",title:"In coperta o al tavolo da carteggio.",text:"Usa IncusGrid in qualsiasi browser o installa l’app Android. Cerca la tua zona di navigazione ed esplorala su smartphone, tablet o laptop.",points:["Nessuna installazione nel browser","App Android su Google Play","Disponibile in 19 lingue"],web:"Apri nel browser",android:"Disponibile su Google Play",phoneAlt:"L’app Android di IncusGrid con le soste delle barche intorno alle Isole Ionie."},final:{title:"Pianifica la tua prossima stagione.",text:"Rotte, soste delle barche, vento, onde e fulmini — un’unica mappa, costruita su molti anni di dati reali.",cta:"Apri la mappa"},disclaimerLabel:"Attenzione",disclaimer:"IncusGrid mostra andamenti storici per la pianificazione. Non è una previsione meteo né un aiuto alla navigazione. Le rotte sono tracciate in modo schematico, e le soste delle barche sono ricavate dalle pause nelle segnalazioni di posizione, non da ormeggi confermati. Prima di uscire in mare controlla sempre le previsioni aggiornate, le carte nautiche ufficiali e le condizioni locali.",footer:{blog:"Blog",legal:"Note legali",privacy:"Informativa sulla privacy",terms:"Termini di servizio",cookies:"Impostazioni cookie",support:"Assistenza",madeWith:"Fatto con",made:"in Portogallo",englishOnly:"Pagine legali in inglese."}},u={path:"/nl",htmlLang:"nl",ogLocale:"nl_NL",meta:{title:"IncusGrid · Plan je zeilseizoen met echte data",description:"Zeilroutes en bootpauzes uit echte overtochten, plus jaren aan wind-, golf- en bliksemdata op één kaart. Plan je volgende seizoen.",keywords:"zeilroutes, zeilreis plannen, ankerplaats, jachthaven, overwinteren, windstatistiek, zeegang, golven, deining, bliksem, onweer, zeilen, jacht, langeafstandszeilen, blauwwaterzeilen"},nav:{routes:"Routes",stays:"Bootpauzes",weather:"Weer",terrain:"Terrein",blog:"Blog",openApp:"Open de kaart"},hero:{position:"Sailing intelligence",titleA:"Niet de zoveelste weer-app.",titleB:"Niet het zoveelste zeilnetwerk.",lead:"IncusGrid maakt van jaren aan data de lokale kennis die elke bemanning nodig heeft voordat ze losgooit: echte bootbewegingen, wind, golven en bliksem op één kaart — zodat je je volgende overtocht plant met de gebundelde kennis van duizenden zeilers.",ctaApp:"Open de kaart",ctaAndroid:"Android-app",heroAlt:"Zeilroutes in de Caribische Zee, van Hispaniola via de Kleine Antillen tot de kust van Zuid-Amerika, getekend uit echte overtochten van zeiljachten.",heroCaption:"Zeilroutes, Caribische Zee · alle maanden",notes:[{label:"Boten",value:"Duizenden"},{label:"Bewegingen",value:"Miljoenen"},{label:"Blikseminslagen",value:"Miljarden"},{label:"Dekking",value:"Wereldwijd"}]},contrast:{kicker:"Geen weersverwachting",title:"De weersverwachting vertelt je over morgen. IncusGrid vertelt je over het seizoen.",text:"Welke oversteek maken bemanningen in juni? Waar overwinteren boten? In welke maand komt de Meltemi, en welke kant van de baai is beter beschut tegen bliksem? Antwoorden die pas zichtbaar worden als je veel jaren tegelijk bekijkt."},chapters:[{id:"routes",number:"01",kicker:"Zeilroutes",title:"Plan oversteken met de ervaring van duizenden bemanningen.",text:"Duizenden echte overtochten laten zien wanneer een oversteek zinvol is, in welke richting, en waar bemanningen vertrekken en aankomen. De heersende wind, goede plekken om op een weergat te wachten en een veilige aanlanding na een nacht op zee zitten er al in. Van Sicilië naar de Ionische Eilanden bijvoorbeeld varen de meeste boten in mei en juni naar het oosten en in september weer terug.",points:["Populariteit per maand en richting","De populairste routes in je huidige kaartbeeld","Deel een route met je bemanning"],image:"route-detail",alt:"De route van Sicilië naar de Ionische Eilanden geselecteerd, met de populariteit per maand en richting.",coords:"38°12′N · 017°30′E",caption:"Sicilië → Ionische Eilanden, per maand en richting"},{id:"route-wind",number:"02",kicker:"Wind langs de route",title:"Ken de wind voordat je losgooit.",text:"Elke route toont de wind die je er kunt verwachten, maand voor maand: waar hij vandaan komt, hoe hard hij waait, hoeveel van de overtocht je aan de wind, met halve wind of met ruime wind zeilt, en hoe vaak de zee kalm blijft. Van Sicilië naar de Ionische Eilanden in mei: wind uit het noordwesten, 3 Bft, meer dan de helft van de tocht met ruime wind.",points:["Heersende wind en windkracht in Beaufort voor elke maand","Aan de wind, halve wind of ruime wind op de koers van de route","Zeegang langs de route"],image:"route-wind",alt:"De routekaart van Sicilië naar de Ionische Eilanden: heersende wind, windkracht in Beaufort, kracht, koers en zeegang voor elke maand, met mei geselecteerd.",coords:"",caption:"Sicilië → Ionische Eilanden, wind in mei",card:!0},{id:"stays",number:"03",kicker:"Bootpauzes",title:"Waar andere boten liggen.",text:"Waar laten bemanningen hun boot in de zomer twee maanden liggen, en waar brengen ze de winter door? Bootpauzes tonen de havens en ankerplaatsen waar boten stillagen — van een paar dagen tot meer dan zes maanden, per seizoen.",points:["Filter op verblijfsduur","Zie in welke maanden boten ergens liggen","Ontdek populaire winterhavens"],image:"stay-detail",alt:"Preveza: gebruikelijke verblijfsduur en de maanden waarin boten er liggen.",coords:"38°57′N · 020°45′E",caption:"Preveza, verblijfsduur en seizoen"},{id:"hotspots",number:"04",kicker:"Hotspots",title:"Vind de rustigere ankerplek.",text:"Waar is het in augustus druk met boten, en waar is nog plek? Hotspots laat per maand zien hoe druk elk vaargebied is. De Ionische Zee en de Saronische Golf kleuren fel, terwijl Andros, een dagtocht van Athene, rustig blijft.",points:["Van rustig tot druk","Elke maand van het jaar","Drukste en rustigste maanden op elk punt"],image:"hotspots",alt:"Hoe druk de Griekse vaargebieden in augustus zijn: druk rond de Ionische Eilanden en in de Saronische Golf, rustig bij Andros, met de puntinspector geopend.",coords:"38°24′N · 023°36′E",caption:"Hotspots, Griekenland, augustus"},{id:"wind",number:"05",kicker:"Wind",title:"Hoeveel noordenwind kun je verwachten?",text:"Kies een richting en een maand: in juli kleurt de centrale Egeïsche Zee diepblauw. Dat is de Meltemi. Tik op een punt bij Mykonos en je ziet dat de wind in juli in 60% van alle uren of meer uit het noorden waait.",points:["Kracht en richting voor elke maand","Wind per tijdstip","Tik op een punt voor de cijfers"],image:"wind",alt:"Hoe vaak de wind in juli uit het noorden waait in de Egeïsche Zee, met de puntdetails geopend bij Mykonos.",coords:"37°36′N · 025°00′E",caption:"Wind uit het noorden, Egeïsche Zee, juli"},{id:"waves",number:"06",kicker:"Golven",title:"Ken de zeegang voordat je vertrekt.",text:"Hoeveel dagen per maand brengen golven van 2,5 m of meer? In januari zie je duidelijk hoe ver de Mistral over de Golf van Lion reikt.",points:["Van kalme tot zeer ruwe zee","Deining en korte steile zee","Elke maand van het jaar"],image:"waves",alt:"Dagen met ruwe zee in de westelijke Middellandse Zee in januari.",coords:"41°00′N · 005°00′E",caption:"Ruwe dagen, westelijke Middellandse Zee, januari"},{id:"potential",number:"07",kicker:"Kansrijke onweersomstandigheden",title:"Waar onweer kan ontstaan.",text:"Het aandeel van de tijd met onweersgunstige omstandigheden, maand na maand — ook op plekken waar onweer had kunnen ontstaan op dagen dat het uitbleef.",points:["Elke maand van het jaar","Tik op een punt voor de cijfers"],image:"potential",alt:"Kansrijke onweersomstandigheden rond Panama in september.",coords:"09°00′N · 079°30′W",caption:"Kansrijke onweersomstandigheden, Panama, september"},{id:"terrain",number:"08",kicker:"Terreinblootstelling",title:"Dezelfde baai, andere afscherming.",text:"Omliggende heuvels kunnen een ankerplaats afschermen tegen bliksem. Terreinblootstelling laat zien hoe goed het terrein elk deel van een baai beschermt, zodat je de betere kant kiest voordat het anker valt.",points:["Vergelijk plekken binnen één baai","Combineer het met historische onweersdagen"],image:"terrain",alt:"Terreinblootstelling in de baai van Komiža op Vis, Kroatië.",coords:"43°02′N · 016°05′E",caption:"Baai van Komiža, Vis",markers:[{x:56.9,y:57.69,text:"Weinig afscherming door het omliggende terrein.",color:"#762a83"},{x:53.84,y:26.35,text:"Enige afscherming door het omliggende terrein.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Meer afscherming door het omliggende terrein.",color:"#5aae61"}]}],story:{kicker:"Ons verhaal",title:"Ontstaan na een bijna-inslag.",text:"In oktober 2024 zeilde ons gezin op de Ionische Zee toen de bliksem vlak naast onze boot insloeg. Dat moment riep een simpele vraag op: liggen we hier veiliger, of aan de andere kant van de baai? IncusGrid begon als het antwoord — en groeide uit tot een kaart met alles wat we vóór dat seizoen hadden willen weten.",more:"Lees het hele verhaal (Engels)",link:`${e}/blog/introducing-incusgrid/`,place:"Igoumenitsa, Griekenland",note:"Waar het idee ontstond"},fromBlog:{kicker:"Van de blog",title:"Dataverhalen van het water.",all:"Alle berichten",note:"Berichten in het Engels."},devices:{kicker:"Web & Android",title:"Aan dek of aan de kaartentafel.",text:"Gebruik IncusGrid in elke browser of installeer de Android-app. Zoek je vaargebied en verken het op telefoon, tablet of laptop.",points:["In de browser zonder installatie","Android-app via Google Play","Beschikbaar in 19 talen"],web:"Openen in de browser",android:"Ontdek het op Google Play",phoneAlt:"IncusGrid-Android-app met bootpauzes rond de Ionische Eilanden."},final:{title:"Plan je volgende seizoen.",text:"Routes, bootpauzes, wind, golven en bliksem — één kaart, gebouwd op vele jaren echte data.",cta:"Open de kaart"},disclaimerLabel:"Let op",disclaimer:"IncusGrid toont historische patronen voor de planning. Het is geen weersverwachting en geen navigatiemiddel. Routes zijn schematisch getekend, en bootpauzes zijn afgeleid uit pauzes in bootmeldingen, niet uit bevestigde ligplaatsen. Controleer altijd de actuele weersverwachting, officiële zeekaarten en de lokale omstandigheden voordat je de zee op gaat.",footer:{blog:"Blog",legal:"Juridische informatie",privacy:"Privacybeleid",terms:"Gebruiksvoorwaarden",cookies:"Cookie-instellingen",support:"Support",madeWith:"Met",made:"gemaakt in Portugal",englishOnly:"Juridische pagina’s in het Engels."}},m={path:"/es",htmlLang:"es",ogLocale:"es_ES",meta:{title:"IncusGrid · Planifica tu temporada de vela con datos reales",description:"Rutas de navegación y pausas de barcos de travesías reales, más años de datos de viento, oleaje y rayos en un solo mapa. Planifica tu próxima temporada.",keywords:"rutas de navegación, navegación de crucero, navegación de altura, fondeadero, fondeo, puerto deportivo, invernada, estadísticas de viento, estado del mar, oleaje, rayos, tormentas, planificar una travesía, velero, vuelta al mundo en velero"},nav:{routes:"Rutas",stays:"Pausas de barcos",weather:"Tiempo",terrain:"Terreno",blog:"Blog",openApp:"Abrir el mapa"},hero:{position:"Sailing intelligence",titleA:"No es otra app del tiempo.",titleB:"No es otra red de navegantes.",lead:"IncusGrid convierte años de datos en el conocimiento local que toda tripulación necesita antes de soltar amarras: movimientos reales de barcos, viento, oleaje y rayos en un solo mapa — para que planifiques tu próxima travesía con el conocimiento colectivo de miles de navegantes.",ctaApp:"Abrir el mapa",ctaAndroid:"App para Android",heroAlt:"Rutas de navegación por el mar Caribe, de La Española a las Antillas Menores y la costa de Sudamérica, trazadas a partir de travesías reales de veleros de crucero.",heroCaption:"Rutas de navegación, mar Caribe · todos los meses",notes:[{label:"Barcos",value:"Miles"},{label:"Movimientos",value:"Millones"},{label:"Rayos",value:"Miles de millones"},{label:"Cobertura",value:"Mundial"}]},contrast:{kicker:"No es un pronóstico",title:"El pronóstico te habla de mañana. IncusGrid te habla de la temporada.",text:"¿Qué travesía hacen las tripulaciones en junio? ¿Dónde pasan el invierno los barcos? ¿Qué mes trae el meltemi, y qué lado de la bahía está más protegido de los rayos? Respuestas que solo aparecen cuando miras muchos años a la vez."},chapters:[{id:"routes",number:"01",kicker:"Rutas de navegación",title:"Planifica travesías con la experiencia de miles de tripulaciones.",text:"Miles de travesías reales muestran cuándo tiene sentido cruzar, en qué dirección, y desde dónde salen y adónde llegan las tripulaciones. Los vientos dominantes, los buenos sitios para esperar una ventana meteorológica y una recalada segura tras una noche en el mar ya vienen incluidos. De Sicilia a las islas Jónicas, por ejemplo, la mayoría de los barcos navegan hacia el este en mayo y junio y vuelven en septiembre.",points:["Popularidad por mes y dirección","Las rutas más populares en tu vista actual del mapa","Comparte una ruta con tu tripulación"],image:"route-detail",alt:"La ruta de Sicilia a las islas Jónicas seleccionada, con su popularidad en cada mes y dirección.",coords:"38°12′N · 017°30′E",caption:"Sicilia → islas Jónicas, por mes y dirección"},{id:"route-wind",number:"02",kicker:"El viento en la ruta",title:"Conoce el viento antes de soltar amarras.",text:"Cada ruta muestra el viento que puedes esperar en ella, mes a mes: de dónde sopla, con qué fuerza, qué parte de la travesía navegas en ceñida, de través o con vientos portantes, y con qué frecuencia el mar se mantiene en calma. De Sicilia a las islas Jónicas en mayo: viento del noroeste, fuerza 3 Beaufort, más de la mitad del camino con vientos portantes.",points:["Viento dominante y fuerza Beaufort para cada mes","Ceñida, través o portantes en el rumbo de la ruta","Estado del mar a lo largo de la ruta"],image:"route-wind",alt:"La ficha de la ruta de Sicilia a las islas Jónicas: viento dominante, fuerza Beaufort, fuerza del viento, rumbo y estado del mar para cada mes, con mayo seleccionado.",coords:"",caption:"Sicilia → islas Jónicas, viento en mayo",card:!0},{id:"stays",number:"03",kicker:"Pausas de barcos",title:"Dónde se quedan otros barcos.",text:"¿Dónde dejan las tripulaciones su barco dos meses en verano, y dónde pasan el invierno? Las pausas de barcos muestran los puertos y fondeaderos donde los barcos se han detenido — desde unos días hasta más de seis meses, según la temporada.",points:["Filtra por duración de la pausa","Descubre en qué meses se quedan los barcos en un lugar","Encuentra puertos populares para invernar"],image:"stay-detail",alt:"Preveza: duración típica de la pausa y meses en los que los barcos se quedan allí.",coords:"38°57′N · 020°45′E",caption:"Preveza, duración de la pausa y temporada"},{id:"hotspots",number:"04",kicker:"Hotspots",title:"Encuentra el fondeadero más tranquilo.",text:"¿Dónde se aglomeran los barcos en agosto y dónde queda sitio? Hotspots muestra, mes a mes, lo concurrida que está cada zona de navegación. El mar Jónico y el golfo Sarónico brillan, mientras Andros, a un día de navegación de Atenas, sigue tranquila.",points:["De tranquilo a concurrido","Cada mes del año","Meses más y menos concurridos en cada punto"],image:"hotspots",alt:"Lo concurridas que están las zonas de navegación griegas en agosto: llenas en torno a las islas Jónicas y en el golfo Sarónico, tranquilas frente a Andros, con el inspector de punto abierto.",coords:"38°24′N · 023°36′E",caption:"Hotspots, Grecia, agosto"},{id:"wind",number:"05",kicker:"Viento",title:"¿Cuánto viento del norte te espera?",text:"Elige una dirección y un mes: en julio, el Egeo central se tiñe de azul intenso. Es el meltemi. Toca un punto cerca de Mykonos y verás que sopla del norte en el 60 % de todas las horas de julio o más.",points:["Fuerza y dirección para cada mes","Viento según la hora del día","Toca cualquier punto para ver sus datos"],image:"wind",alt:"Con qué frecuencia sopla el viento del norte en el mar Egeo en julio, con el inspector de puntos abierto cerca de Mykonos.",coords:"37°36′N · 025°00′E",caption:"Viento del norte, mar Egeo, julio"},{id:"waves",number:"06",kicker:"Oleaje",title:"Conoce el estado del mar antes de zarpar.",text:"¿Cuántos días al mes traen olas de 2,5 m o más? En enero se ve con claridad hasta dónde llega el mistral en el golfo de León.",points:["De mar en calma a mar muy gruesa","Mar de fondo y mar corta y empinada","Todos los meses del año"],image:"waves",alt:"Días de mar agitada en el Mediterráneo occidental en enero.",coords:"41°00′N · 005°00′E",caption:"Días agitados, Mediterráneo occidental, enero"},{id:"potential",number:"07",kicker:"Potencial de tormentas",title:"Dónde pueden formarse tormentas.",text:"La proporción del tiempo con condiciones favorables a tormentas, mes a mes — incluso en lugares donde podrían haberse formado tormentas los días en que no se formó ninguna.",points:["Todos los meses del año","Toca cualquier punto para ver sus datos"],image:"potential",alt:"Potencial de tormentas alrededor de Panamá en septiembre.",coords:"09°00′N · 079°30′W",caption:"Potencial de tormentas, Panamá, septiembre"},{id:"terrain",number:"08",kicker:"Exposición del terreno",title:"Misma bahía, distinta protección.",text:"Las colinas de alrededor pueden proteger un fondeadero de los rayos. La Exposición del terreno muestra lo bien que el terreno protege cada parte de una bahía, para que elijas el mejor lado antes de fondear.",points:["Compara puntos dentro de una misma bahía","Combínala con los días de tormenta históricos"],image:"terrain",alt:"Exposición del terreno en la bahía de Komiža, en la isla de Vis, Croacia.",coords:"43°02′N · 016°05′E",caption:"Bahía de Komiža, Vis",markers:[{x:56.9,y:57.69,text:"Poca protección del terreno circundante.",color:"#762a83"},{x:53.84,y:26.35,text:"Cierta protección del terreno circundante.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Mayor protección del terreno circundante.",color:"#5aae61"}]}],story:{kicker:"Nuestra historia",title:"Nació de un buen susto.",text:"En octubre de 2024, nuestra familia navegaba por el mar Jónico cuando un rayo cayó justo al lado de nuestro barco. Ese momento nos dejó una pregunta sencilla: ¿estamos más seguros aquí o al otro lado de la bahía? IncusGrid empezó como la respuesta — y se convirtió en un mapa de todo lo que nos habría gustado saber antes de aquella temporada.",more:"Lee la historia completa (en inglés)",link:`${e}/blog/introducing-incusgrid/`,place:"Igumenitsa, Grecia",note:"Donde nació la idea"},fromBlog:{kicker:"Del blog",title:"Historias de datos desde el agua.",all:"Todos los artículos",note:"Artículos en inglés."},devices:{kicker:"Web & Android",title:"En cubierta o en la mesa de cartas.",text:"Usa IncusGrid en cualquier navegador o instala la app para Android. Busca tu zona de navegación y explórala en el móvil, la tableta o el portátil.",points:["Sin instalar nada en el navegador","App para Android en Google Play","Disponible en 19 idiomas"],web:"Abrir en el navegador",android:"Disponible en Google Play",phoneAlt:"La app de IncusGrid para Android mostrando pausas de barcos alrededor de las islas Jónicas."},final:{title:"Planifica tu próxima temporada.",text:"Rutas, pausas de barcos, viento, oleaje y rayos — un solo mapa, construido con muchos años de datos reales.",cta:"Abrir el mapa"},disclaimerLabel:"Precaución",disclaimer:"IncusGrid muestra patrones históricos para planificar. No es un pronóstico del tiempo ni una ayuda a la navegación. Las rutas se dibujan de forma esquemática, y las pausas de barcos se deducen de interrupciones en los reportes de posición, no de amarres confirmados. Consulta siempre los pronósticos actuales, las cartas náuticas oficiales y las condiciones locales antes de salir a navegar.",footer:{blog:"Blog",legal:"Aviso legal",privacy:"Política de privacidad",terms:"Términos del servicio",cookies:"Configuración de cookies",support:"Soporte",madeWith:"Hecho con",made:"en Portugal",englishOnly:"Páginas legales en inglés."}},c={path:"/sv",htmlLang:"sv",ogLocale:"sv_SE",meta:{title:"IncusGrid · Planera din seglingssäsong med riktiga data",description:"Seglingsrutter och båtpauser från verkliga överfarter, plus år av vind-, våg- och blixtdata på en karta. Planera nästa säsong.",keywords:"seglingsrutter, långsegling, segla jorden runt, ankarplats, gästhamn, marina, vinterförvaring, vindstatistik, sjögång, vågor, dyning, blixtar, åska, segling, segelbåt, ruttplanering"},nav:{routes:"Rutter",stays:"Båtpauser",weather:"Väder",terrain:"Terräng",blog:"Blogg",openApp:"Öppna kartan"},hero:{position:"Sailing intelligence",titleA:"Inte ännu en väderapp.",titleB:"Inte ännu ett seglarnätverk.",lead:"IncusGrid gör år av data till den lokalkännedom varje besättning behöver innan man kastar loss: verkliga båtrörelser, vind, vågor och blixtar på en karta — så att du kan planera nästa överfart med den samlade kunskapen från tusentals seglare.",ctaApp:"Öppna kartan",ctaAndroid:"Android-app",heroAlt:"Seglingsrutter i Karibiska havet, från Hispaniola via Små Antillerna till Sydamerikas kust, ritade utifrån verkliga överfarter med långfärdsbåtar.",heroCaption:"Seglingsrutter, Karibiska havet · alla månader",notes:[{label:"Båtar",value:"Tusentals"},{label:"Rörelser",value:"Miljoner"},{label:"Blixtnedslag",value:"Miljarder"},{label:"Täckning",value:"Hela världen"}]},contrast:{kicker:"Ingen väderprognos",title:"Prognosen berättar om i morgon. IncusGrid berättar om säsongen.",text:"Vilken överfart gör besättningar i juni? Var övervintrar båtarna? Vilken månad kommer meltemin, och vilken sida av viken är bättre skyddad mot blixtar? Svar som syns först när man tittar på många år samtidigt."},chapters:[{id:"routes",number:"01",kicker:"Seglingsrutter",title:"Planera överfarter med tusentals besättningars erfarenhet.",text:"Tusentals verkliga överfarter visar när en överfart är rimlig, i vilken riktning, och var besättningar kastar loss och kommer fram. Förhärskande vindar, bra ställen att vänta in ett väderfönster och en säker angöring efter en natt till sjöss finns redan inbyggda. Från Sicilien till Joniska öarna går till exempel de flesta båtar österut i maj och juni och seglar tillbaka i september.",points:["Popularitet per månad och riktning","De populäraste rutterna i din aktuella kartvy","Dela en rutt med din besättning"],image:"route-detail",alt:"Rutten från Sicilien till Joniska öarna vald, med hur populär den är varje månad och i varje riktning.",coords:"38°12′N · 017°30′E",caption:"Sicilien → Joniska öarna, per månad och riktning"},{id:"route-wind",number:"02",kicker:"Vind längs rutten",title:"Känn vinden innan du kastar loss.",text:"Varje rutt visar vinden du kan räkna med, månad för månad: varifrån den kommer, hur hårt den blåser, hur stor del av överfarten du seglar i bidevind, halvvind eller undanvind, och hur ofta sjön förblir lugn. Från Sicilien till Joniska öarna i maj: vind från nordväst, 3 Beaufort, mer än halva vägen i undanvind.",points:["Förhärskande vind och vindstyrka i Beaufort för varje månad","Bidevind, halvvind eller undanvind på ruttens kurs","Sjögång längs rutten"],image:"route-wind",alt:"Ruttkortet för Sicilien till Joniska öarna: förhärskande vind, vindstyrka i Beaufort, styrka, kurs och sjögång för varje månad, med maj valt.",coords:"",caption:"Sicilien → Joniska öarna, vind i maj",card:!0},{id:"stays",number:"03",kicker:"Båtpauser",title:"Där andra båtar ligger.",text:"Var lämnar besättningar båten i två månader på sommaren, och var tillbringar de vintern? Båtpauser visar hamnarna och ankarplatserna där båtar gjort uppehåll — från några dagar till mer än sex månader, per säsong.",points:["Filtrera på hur länge båtarna ligger","Se vilka månader båtar ligger på en plats","Hitta populära vinterhamnar"],image:"stay-detail",alt:"Preveza: typisk vistelse och de månader då båtar ligger där.",coords:"38°57′N · 020°45′E",caption:"Preveza, vistelsens längd och säsong"},{id:"hotspots",number:"04",kicker:"Hotspots",title:"Hitta den lugnare ankringsplatsen.",text:"Var trängs båtarna i augusti, och var finns det fortfarande plats? Hotspots visar månad för månad hur livligt varje seglingsområde är. Joniska havet och Saroniska viken lyser, medan Andros, en dagsetapp från Aten, förblir lugnt.",points:["Från lugnt till fullt","Årets alla månader","Livligaste och lugnaste månader på varje punkt"],image:"hotspots",alt:"Hur livliga de grekiska seglingsområdena är i augusti: fullt kring Joniska öarna och i Saroniska viken, lugnt utanför Andros, med punktinspektören öppen.",coords:"38°24′N · 023°36′E",caption:"Hotspots, Grekland, augusti"},{id:"wind",number:"05",kicker:"Vind",title:"Hur mycket nordlig vind kan du räkna med?",text:"Välj riktning och månad: i juli blir centrala Egeiska havet djupblått. Det är meltemin. Tryck på en punkt nära Mykonos så ser du att vinden blåser från norr under 60 % av alla timmar i juli, eller mer.",points:["Styrka och riktning för varje månad","Vind efter tid på dygnet","Tryck på en punkt för att se siffrorna"],image:"wind",alt:"Hur ofta vinden blåser från norr i Egeiska havet i juli, med punktdetaljerna öppna nära Mykonos.",coords:"37°36′N · 025°00′E",caption:"Vind från norr, Egeiska havet, juli"},{id:"waves",number:"06",kicker:"Vågor",title:"Känn sjögången innan du ger dig iväg.",text:"Hur många dagar per månad har vågor på 2,5 m eller mer? I januari syns tydligt hur långt mistralen når ut över Lionbukten.",points:["Från lugn till mycket grov sjö","Dyning och kort, brant sjö","Årets alla månader"],image:"waves",alt:"Dagar med grov sjö i västra Medelhavet i januari.",coords:"41°00′N · 005°00′E",caption:"Dagar med grov sjö, västra Medelhavet, januari"},{id:"potential",number:"07",kicker:"Åskpotential",title:"Där åska kan bildas.",text:"Andelen av tiden med åskgynnsamma förhållanden, månad för månad — även där åska hade kunnat bildas under dagar då ingen uppstod.",points:["Årets alla månader","Tryck på en punkt för att se siffrorna"],image:"potential",alt:"Åskpotential runt Panama i september.",coords:"09°00′N · 079°30′W",caption:"Åskpotential, Panama, september"},{id:"terrain",number:"08",kicker:"Terrängexponering",title:"Samma vik, olika skydd.",text:"Omgivande kullar kan skärma av en ankarplats mot blixtar. Terrängexponering visar hur väl terrängen skyddar varje del av en vik, så att du kan välja den bättre sidan innan ankaret går.",points:["Jämför platser i samma vik","Kombinera med historiska åskdagar"],image:"terrain",alt:"Terrängexponering i Komižaviken på Vis, Kroatien.",coords:"43°02′N · 016°05′E",caption:"Komižaviken, Vis",markers:[{x:56.9,y:57.69,text:"Liten avskärmning från omgivande terräng.",color:"#762a83"},{x:53.84,y:26.35,text:"Viss avskärmning från omgivande terräng.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Större avskärmning från omgivande terräng.",color:"#5aae61"}]}],story:{kicker:"Vår historia",title:"Det började med ett nära ögat.",text:"I oktober 2024 seglade vår familj i Joniska havet när blixten slog ner precis bredvid båten. Det ögonblicket väckte en enkel fråga: ligger vi säkrare här, eller på andra sidan viken? IncusGrid började som svaret — och växte till en karta med allt vi hade velat veta före den säsongen.",more:"Läs hela historien (på engelska)",link:`${e}/blog/introducing-incusgrid/`,place:"Igoumenitsa, Grekland",note:"Där idén föddes"},fromBlog:{kicker:"Från bloggen",title:"Datahistorier från sjön.",all:"Alla inlägg",note:"Inlägg på engelska."},devices:{kicker:"Webb & Android",title:"På däck eller vid navbordet.",text:"Använd IncusGrid i valfri webbläsare eller installera Android-appen. Sök fram ditt seglingsområde och utforska det i mobilen, på surfplattan eller datorn.",points:["Ingen installation i webbläsaren","Android-app på Google Play","Finns på 19 språk"],web:"Öppna i webbläsaren",android:"Hämta på Google Play",phoneAlt:"IncusGrids Android-app med båtpauser runt Joniska öarna."},final:{title:"Planera nästa säsong.",text:"Rutter, båtpauser, vind, vågor och blixtar — en karta, byggd på många års verkliga data.",cta:"Öppna kartan"},disclaimerLabel:"Observera",disclaimer:"IncusGrid visar historiska mönster för planering. Det är ingen väderprognos och inget navigationshjälpmedel. Rutterna är schematiskt ritade, och båtpauser härleds ur uppehåll i båtarnas positionsrapporter, inte ur bekräftade båtplatser. Kontrollera alltid aktuella prognoser, officiella sjökort och lokala förhållanden innan du går till sjöss.",footer:{blog:"Blogg",legal:"Juridisk information",privacy:"Integritetspolicy",terms:"Användarvillkor",cookies:"Cookieinställningar",support:"Support",madeWith:"Gjord med",made:"i Portugal",englishOnly:"Juridiska sidor på engelska."}},p={path:"/da",htmlLang:"da",ogLocale:"da_DK",meta:{title:"IncusGrid · Planlæg din sejlsæson med rigtige data",description:"Sejlruter og bådpauser fra rigtige overfarter, plus mange års vind-, bølge- og lyndata på ét kort. Planlæg din næste sæson.",keywords:"sejlruter, langtursejlads, jordomsejling, ankerplads, lystbådehavn, marina, vinteroplag, vindstatistik, søgang, bølger, dønning, lyn, tordenvejr, sejlads, sejlbåd, ruteplanlægning"},nav:{routes:"Ruter",stays:"Bådpauser",weather:"Vejr",terrain:"Terræn",blog:"Blog",openApp:"Åbn kortet"},hero:{position:"Sailing intelligence",titleA:"Ikke endnu en vejr-app.",titleB:"Ikke endnu et sejlernetværk.",lead:"IncusGrid gør års data til det lokalkendskab, enhver besætning har brug for, før den kaster los: rigtige bådbevægelser, vind, bølger og lyn på ét kort — så du kan planlægge din næste overfart med den samlede viden fra tusindvis af sejlere.",ctaApp:"Åbn kortet",ctaAndroid:"Android-app",heroAlt:"Sejlruter i Det Caribiske Hav, fra Hispaniola over De Små Antiller til Sydamerikas kyst, tegnet ud fra rigtige overfarter med langtursbåde.",heroCaption:"Sejlruter, Det Caribiske Hav · alle måneder",notes:[{label:"Både",value:"Tusindvis"},{label:"Bevægelser",value:"Millioner"},{label:"Lynnedslag",value:"Milliarder"},{label:"Dækning",value:"Hele verden"}]},contrast:{kicker:"Ikke en vejrudsigt",title:"Vejrudsigten fortæller dig om i morgen. IncusGrid fortæller dig om sæsonen.",text:"Hvilken overfart tager besætninger i juni? Hvor overvintrer bådene? Hvilken måned bringer meltemien, og hvilken side af bugten er bedst skærmet mod lyn? Svar, der først viser sig, når man ser på mange år på én gang."},chapters:[{id:"routes",number:"01",kicker:"Sejlruter",title:"Planlæg overfarter med tusindvis af besætningers erfaring.",text:"Tusindvis af rigtige overfarter viser, hvornår en overfart giver mening, i hvilken retning, og hvor besætninger kaster los og ankommer. De fremherskende vinde, gode steder at vente på et vejrvindue og en sikker ansejling efter en nat på havet er allerede bygget ind. Fra Sicilien til De Joniske Øer sejler de fleste både for eksempel mod øst i maj og juni og tilbage igen i september.",points:["Popularitet pr. måned og retning","De mest populære ruter i dit aktuelle kortudsnit","Del en rute med din besætning"],image:"route-detail",alt:"Ruten fra Sicilien til De Joniske Øer valgt, med hvor populær den er i hver måned og retning.",coords:"38°12′N · 017°30′E",caption:"Sicilien → De Joniske Øer, efter måned og retning"},{id:"route-wind",number:"02",kicker:"Vind langs ruten",title:"Kend vinden, før du kaster los.",text:"Hver rute viser den vind, du kan forvente, måned for måned: hvor den kommer fra, hvor hårdt den blæser, hvor meget af overfarten du sejler i bidevind, halvvind eller rum vind, og hvor ofte søen forbliver rolig. Fra Sicilien til De Joniske Øer i maj: vind fra nordvest, 3 Beaufort, mere end halvdelen af vejen i rum vind.",points:["Fremherskende vind og vindstyrke i Beaufort for hver måned","Bidevind, halvvind eller rum vind på rutens kurs","Søgang langs ruten"],image:"route-wind",alt:"Rutekortet for Sicilien til De Joniske Øer: fremherskende vind, vindstyrke i Beaufort, styrke, kurs og søgang for hver måned, med maj valgt.",coords:"",caption:"Sicilien → De Joniske Øer, vind i maj",card:!0},{id:"stays",number:"03",kicker:"Bådpauser",title:"Hvor andre både ligger.",text:"Hvor lader besætninger båden ligge i to måneder om sommeren, og hvor tilbringer de vinteren? Bådpauser viser de havne og ankerpladser, hvor både har holdt pause — fra nogle få dage til mere end seks måneder, efter sæson.",points:["Filtrer efter opholdets længde","Se, i hvilke måneder både ligger et sted","Find populære vinterhavne"],image:"stay-detail",alt:"Preveza: typisk opholdslængde og de måneder, hvor både ligger der.",coords:"38°57′N · 020°45′E",caption:"Preveza, opholdslængde og sæson"},{id:"hotspots",number:"04",kicker:"Hotspots",title:"Find den roligere ankerplads.",text:"Hvor trænges bådene i august, og hvor er der stadig plads? Hotspots viser måned for måned, hvor travlt hvert sejlområde er. Det Joniske Hav og Saronske Bugt lyser op, mens Andros, en dagssejlads fra Athen, forbliver roligt.",points:["Fra roligt til fyldt","Hver måned i året","Travleste og roligste måneder på ethvert punkt"],image:"hotspots",alt:"Hvor travle de græske sejlområder er i august: fyldt omkring De Joniske Øer og i Saronske Bugt, roligt ud for Andros, med punktinspektøren åben.",coords:"38°24′N · 023°36′E",caption:"Hotspots, Grækenland, august"},{id:"wind",number:"05",kicker:"Vind",title:"Hvor meget nordenvind skal du regne med?",text:"Vælg en retning og en måned: i juli bliver det centrale Ægæiske Hav dybblåt. Det er meltemien. Tryk på et punkt ved Mykonos, og du ser, at vinden blæser fra nord i 60 % af alle timer i juli eller mere.",points:["Styrke og retning for hver måned","Vind efter tid på døgnet","Tryk på et punkt for at se tallene"],image:"wind",alt:"Hvor ofte vinden blæser fra nord i Det Ægæiske Hav i juli, med punktdetaljerne åbne ved Mykonos.",coords:"37°36′N · 025°00′E",caption:"Vind fra nord, Det Ægæiske Hav, juli"},{id:"waves",number:"06",kicker:"Bølger",title:"Kend søgangen, før du stikker til søs.",text:"Hvor mange dage om måneden giver bølger på 2,5 m eller mere? I januar ser man tydeligt, hvor langt mistralen rækker ud over Lionbugten.",points:["Fra rolig til meget hård sø","Dønning og kort, stejl sø","Hver måned i året"],image:"waves",alt:"Dage med hård sø i det vestlige Middelhav i januar.",coords:"41°00′N · 005°00′E",caption:"Hårde dage, det vestlige Middelhav, januar"},{id:"potential",number:"07",kicker:"Tordenpotentiale",title:"Hvor tordenvejr kan opstå.",text:"Andelen af tiden med forhold, der fremmer tordenvejr, måned for måned — også steder, hvor tordenvejr kunne være opstået på dage, hvor der ikke kom noget.",points:["Hver måned i året","Tryk på et punkt for at se tallene"],image:"potential",alt:"Tordenpotentiale omkring Panama i september.",coords:"09°00′N · 079°30′W",caption:"Tordenpotentiale, Panama, september"},{id:"terrain",number:"08",kicker:"Terræneksponering",title:"Samme bugt, forskelligt læ.",text:"Omkringliggende bakker kan skærme en ankerplads mod lyn. Terræneksponering viser, hvor godt terrænet beskytter hver del af en bugt, så du kan vælge den bedste side, før ankeret går.",points:["Sammenlign steder i samme bugt","Kombinér med historiske tordendage"],image:"terrain",alt:"Terræneksponering i Komiža-bugten på Vis, Kroatien.",coords:"43°02′N · 016°05′E",caption:"Komiža-bugten, Vis",markers:[{x:56.9,y:57.69,text:"Ringe afskærmning fra det omgivende terræn.",color:"#762a83"},{x:53.84,y:26.35,text:"Nogen afskærmning fra det omgivende terræn.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Større afskærmning fra det omgivende terræn.",color:"#5aae61"}]}],story:{kicker:"Vores historie",title:"Født af et skræmmende øjeblik.",text:"I oktober 2024 sejlede vores familie i Det Joniske Hav, da lynet slog ned lige ved siden af vores båd. Det øjeblik rejste et enkelt spørgsmål: Ligger vi mere sikkert her eller på den anden side af bugten? IncusGrid begyndte som svaret — og voksede til et kort med alt det, vi gerne ville have vidst før den sæson.",more:"Læs hele historien (på engelsk)",link:`${e}/blog/introducing-incusgrid/`,place:"Igoumenitsa, Grækenland",note:"Hvor idéen blev født"},fromBlog:{kicker:"Fra bloggen",title:"Datahistorier fra vandet.",all:"Alle indlæg",note:"Indlæg på engelsk."},devices:{kicker:"Web & Android",title:"På dækket eller ved kortbordet.",text:"Brug IncusGrid i enhver browser, eller installér Android-appen. Søg dit sejlområde frem, og udforsk det på telefon, tablet eller bærbar.",points:["Ingen installation i browseren","Android-app på Google Play","Fås på 19 sprog"],web:"Åbn i browseren",android:"Hent den på Google Play",phoneAlt:"IncusGrids Android-app med bådpauser omkring De Joniske Øer."},final:{title:"Planlæg din næste sæson.",text:"Ruter, bådpauser, vind, bølger og lyn — ét kort, bygget på mange års rigtige data.",cta:"Åbn kortet"},disclaimerLabel:"Bemærk",disclaimer:"IncusGrid viser historiske mønstre til planlægning. Det er hverken en vejrudsigt eller et navigationshjælpemiddel. Ruterne er tegnet skematisk, og bådpauser er udledt af pauser i bådenes positionsmeldinger, ikke af bekræftede bådpladser. Tjek altid aktuelle vejrudsigter, officielle søkort og de lokale forhold, før du stikker til søs.",footer:{blog:"Blog",legal:"Juridisk information",privacy:"Privatlivspolitik",terms:"Brugsvilkår",cookies:"Cookieindstillinger",support:"Support",madeWith:"Lavet med",made:"i Portugal",englishOnly:"Juridiske sider på engelsk."}},g={path:"/nb",htmlLang:"nb",ogLocale:"nb_NO",meta:{title:"IncusGrid · Planlegg seilsesongen med ekte data",description:"Seilruter og båtpauser fra ekte seilaser, pluss mange års data om vind, bølger og lyn på ett kart. Planlegg neste sesong.",keywords:"seilruter, langtur, langturseiling, ankringsplass, gjestehavn, marina, vinteropplag, vindstatistikk, sjøgang, bølger, lyn, tordenvær, turplanlegging, seilbåt, seiling Middelhavet"},nav:{routes:"Ruter",stays:"Båtpauser",weather:"Vær",terrain:"Terreng",blog:"Blogg",openApp:"Åpne kartet"},hero:{position:"Sailing intelligence",titleA:"Ikke enda en vær-app.",titleB:"Ikke enda et seilernettverk.",lead:"IncusGrid gjør år med data om til lokalkunnskapen ethvert mannskap trenger før de kaster loss: ekte båtbevegelser, vind, bølger og lyn på ett kart — så du kan planlegge neste etappe med den samlede kunnskapen til tusenvis av seilere.",ctaApp:"Åpne kartet",ctaAndroid:"Android-app",heroAlt:"Seilruter i Det karibiske hav, fra Hispaniola til De små Antiller og kysten av Sør-Amerika, tegnet ut fra ekte seilaser med langturbåter.",heroCaption:"Seilruter, Det karibiske hav · alle måneder",notes:[{label:"Båter",value:"Tusenvis"},{label:"Bevegelser",value:"Millioner"},{label:"Lynnedslag",value:"Milliarder"},{label:"Dekning",value:"Hele verden"}]},contrast:{kicker:"Ikke en værmelding",title:"Værmeldingen forteller deg om i morgen. IncusGrid forteller deg om sesongen.",text:"Hvilken overfart tar mannskapene i juni? Hvor ligger båtene om vinteren? Hvilken måned bringer meltemien, og hvilken side av bukta er best skjermet mot lyn? Svar som først viser seg når du ser mange år under ett."},chapters:[{id:"routes",number:"01",kicker:"Seilruter",title:"Planlegg overfarter med erfaringen til tusenvis av mannskaper.",text:"Tusenvis av ekte seilaser viser når en overfart gir mening, i hvilken retning, og hvor mannskaper legger ut og kommer fram. De rådende vindene, gode steder å vente på et værvindu og en trygg landkjenning etter en natt på sjøen ligger allerede i dataene. Fra Sicilia til De joniske øyer seiler for eksempel de fleste båtene østover i mai og juni og tilbake i september.",points:["Popularitet per måned og retning","De mest populære rutene i kartutsnittet ditt","Del en rute med mannskapet ditt"],image:"route-detail",alt:"Ruten fra Sicilia til De joniske øyer valgt, med hvor populær den er i hver måned og retning.",coords:"38°12′N · 017°30′E",caption:"Sicilia → De joniske øyer, per måned og retning"},{id:"route-wind",number:"02",kicker:"Vind langs ruten",title:"Kjenn vinden før du legger ut.",text:"Hver rute viser vinden du kan vente deg, måned for måned: hvor den kommer fra, hvor hardt den blåser, hvor mye av overfarten du seiler i bidevind, halvvind eller undavind, og hvor ofte sjøen holder seg rolig. Fra Sicilia til De joniske øyer i mai: vind fra nordvest, 3 Beaufort, mer enn halve veien i undavind.",points:["Rådende vind og vindstyrke i Beaufort for hver måned","Bidevind, halvvind eller undavind på rutens kurs","Sjøgang langs ruten"],image:"route-wind",alt:"Rutekortet for Sicilia til De joniske øyer: rådende vind, vindstyrke i Beaufort, styrke, kurs og sjøgang for hver måned, med mai valgt.",coords:"",caption:"Sicilia → De joniske øyer, vind i mai",card:!0},{id:"stays",number:"03",kicker:"Båtpauser",title:"Hvor andre båter ligger.",text:"Hvor lar mannskaper båten ligge i to måneder om sommeren, og hvor tilbringer de vinteren? Båtpauser viser havnene og ankringsplassene der båter har tatt pause — fra noen få dager til mer enn seks måneder, etter sesong.",points:["Filtrer etter liggetid","Se i hvilke måneder båter ligger på et sted","Finn populære vinterhavner"],image:"stay-detail",alt:"Preveza: typisk liggetid og månedene da båter ligger der.",coords:"38°57′N · 020°45′E",caption:"Preveza, liggetid og sesong"},{id:"hotspots",number:"04",kicker:"Hotspots",title:"Finn den roligere ankringsplassen.",text:"Hvor trenges båtene i august, og hvor er det fortsatt plass? Hotspots viser måned for måned hvor travelt hvert seilområde er. Det joniske hav og Saronbukta lyser opp, mens Andros, en dagsseilas fra Athen, forblir rolig.",points:["Fra rolig til fullt","Hver måned i året","Travleste og roligste måneder på ethvert punkt"],image:"hotspots",alt:"Hvor travle de greske seilområdene er i august: fullt rundt De joniske øyer og i Saronbukta, rolig utenfor Andros, med punktinspektøren åpen.",coords:"38°24′N · 023°36′E",caption:"Hotspots, Hellas, august"},{id:"wind",number:"05",kicker:"Vind",title:"Hvor mye nordavind kan du vente deg?",text:"Velg retning og måned: I juli blir det sentrale Egeerhavet dypblått. Det er meltemien. Trykk på et punkt ved Mykonos, og du ser at vinden kommer fra nord i 60 % eller mer av alle timene i juli.",points:["Styrke og retning for hver måned","Vind etter tid på døgnet","Trykk på et punkt for å se tallene"],image:"wind",alt:"Hvor ofte vinden blåser fra nord i Egeerhavet i juli, med punktdetaljene åpne ved Mykonos.",coords:"37°36′N · 025°00′E",caption:"Vind fra nord, Egeerhavet, juli"},{id:"waves",number:"06",kicker:"Bølger",title:"Kjenn sjøgangen før du legger ut.",text:"Hvor mange dager i måneden gir bølger på 2,5 m eller mer? I januar ser du tydelig hvor langt mistralen når ut over Lionbukta.",points:["Fra rolig til svært grov sjø","Dønning og kort, bratt sjø","Hver måned i året"],image:"waves",alt:"Dager med grov sjø i det vestlige Middelhavet i januar.",coords:"41°00′N · 005°00′E",caption:"Dager med grov sjø, vestlige Middelhavet, januar"},{id:"potential",number:"07",kicker:"Tordenværpotensial",title:"Hvor tordenvær kan bygge seg opp.",text:"Andelen av tiden med forhold som fremmer tordenvær, måned for måned — også der tordenvær kunne ha bygget seg opp på dager da det ikke ble noe.",points:["Hver måned i året","Trykk på et punkt for å se tallene"],image:"potential",alt:"Tordenværpotensial rundt Panama i september.",coords:"09°00′N · 079°30′W",caption:"Tordenværpotensial, Panama, september"},{id:"terrain",number:"08",kicker:"Terrengeksponering",title:"Samme bukt, ulik skjerming.",text:"Åsene rundt kan skjerme en ankringsplass mot lyn. Terrengeksponering viser hvor godt terrenget beskytter hver del av en bukt, så du kan velge den beste siden før ankeret går.",points:["Sammenlign steder i samme bukt","Kombiner med historiske tordendager"],image:"terrain",alt:"Terrengeksponering i bukta ved Komiža på Vis, Kroatia.",coords:"43°02′N · 016°05′E",caption:"Bukta ved Komiža, Vis",markers:[{x:56.9,y:57.69,text:"Liten skjerming fra terrenget rundt.",color:"#762a83"},{x:53.84,y:26.35,text:"Noe skjerming fra terrenget rundt.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Sterkere skjerming fra terrenget rundt.",color:"#5aae61"}]}],story:{kicker:"Vår historie",title:"Født av en nestenulykke.",text:"I oktober 2024 seilte familien vår i Det joniske hav da lynet slo ned rett ved siden av båten. Det øyeblikket reiste et enkelt spørsmål: Er vi tryggere her, eller på den andre siden av bukta? IncusGrid begynte som svaret — og vokste til et kart over alt vi skulle ønske vi hadde visst før den sesongen.",more:"Les hele historien (på engelsk)",link:`${e}/blog/introducing-incusgrid/`,place:"Igoumenitsa, Hellas",note:"Der ideen ble født"},fromBlog:{kicker:"Fra bloggen",title:"Datahistorier fra sjøen.",all:"Alle innlegg",note:"Innlegg på engelsk."},devices:{kicker:"Web & Android",title:"På dekk eller ved kartbordet.",text:"Bruk IncusGrid i hvilken som helst nettleser, eller installer Android-appen. Søk opp seilområdet ditt og utforsk det på mobil, nettbrett eller laptop.",points:["Ingen installasjon i nettleseren","Android-app på Google Play","Tilgjengelig på 19 språk"],web:"Åpne i nettleseren",android:"Last ned på Google Play",phoneAlt:"IncusGrid-appen for Android med båtpauser rundt De joniske øyer."},final:{title:"Planlegg neste sesong.",text:"Ruter, båtpauser, vind, bølger og lyn — ett kart, bygget på mange år med ekte data.",cta:"Åpne kartet"},disclaimerLabel:"Viktig",disclaimer:"IncusGrid viser historiske mønstre for planlegging. Det er ingen værmelding og ikke et navigasjonshjelpemiddel. Rutene er tegnet skjematisk, og båtpauser er utledet fra pauser i båtenes posisjonsmeldinger, ikke fra bekreftede båtplasser. Sjekk alltid oppdaterte værmeldinger, offisielle sjøkart og lokale forhold før du legger ut.",footer:{blog:"Blogg",legal:"Juridisk informasjon",privacy:"Personvern",terms:"Vilkår for bruk",cookies:"Innstillinger for informasjonskapsler",support:"Brukerstøtte",madeWith:"Laget med",made:"i Portugal",englishOnly:"Juridiske sider er på engelsk."}},k={path:"/fi",htmlLang:"fi",ogLocale:"fi_FI",meta:{title:"IncusGrid · Suunnittele purjehduskautesi oikealla datalla",description:"Purjehdusreitit ja veneiden tauot todellisista purjehduksista sekä vuosien tuuli-, aalto- ja salamatiedot yhdellä kartalla. Suunnittele seuraava kautesi.",keywords:"purjehdusreitit, matkapurjehdus, ankkuripaikka, vierassatama, marina, talvisäilytys, tuulitilasto, merenkäynti, aallokko, salamat, ukkonen, purjehduksen suunnittelu, purjevene, Välimeren purjehdus"},nav:{routes:"Reitit",stays:"Veneiden tauot",weather:"Sää",terrain:"Maasto",blog:"Blogi",openApp:"Avaa kartta"},hero:{position:"Sailing intelligence",titleA:"Ei taas yksi sääsovellus.",titleB:"Ei taas yksi purjehtijoiden yhteisö.",lead:"IncusGrid muuttaa vuosien datan paikallistuntemukseksi, jota jokainen miehistö tarvitsee ennen irrottautumista: todelliset veneliikkeet, tuuli, aallot ja salamat yhdellä kartalla — jotta voit suunnitella seuraavan purjehduksesi tuhansien purjehtijoiden yhteisellä tiedolla.",ctaApp:"Avaa kartta",ctaAndroid:"Android-sovellus",heroAlt:"Purjehdusreitit Karibianmerellä Hispaniolalta Pienille Antilleille ja Etelä-Amerikan rannikolle, piirretty matkaveneiden todellisista purjehduksista.",heroCaption:"Purjehdusreitit, Karibianmeri · kaikki kuukaudet",notes:[{label:"Veneitä",value:"Tuhansia"},{label:"Liikkeitä",value:"Miljoonia"},{label:"Salamaniskuja",value:"Miljardeja"},{label:"Kattavuus",value:"Koko maailma"}]},contrast:{kicker:"Ei ennuste",title:"Ennuste kertoo huomisesta. IncusGrid kertoo koko kaudesta.",text:"Minkä ylityksen miehistöt tekevät kesäkuussa? Missä veneet talvehtivat? Mikä kuukausi tuo meltemin, ja kumpi lahden puoli on paremmin suojassa salamoilta? Vastaukset näkyvät vasta, kun katsoo monta vuotta kerralla."},chapters:[{id:"routes",number:"01",kicker:"Purjehdusreitit",title:"Suunnittele ylitykset tuhansien miehistöjen kokemuksella.",text:"Tuhannet todelliset purjehdukset näyttävät, milloin ylitys on järkevä, mihin suuntaan, ja mistä miehistöt lähtevät ja minne saapuvat. Vallitsevat tuulet, hyvät paikat sääikkunan odottamiseen ja turvallinen maihintulo yön yli kestäneen osuuden jälkeen ovat jo mukana. Esimerkiksi Sisiliasta Joonian saarille useimmat veneet purjehtivat itään touko- ja kesäkuussa ja palaavat syyskuussa.",points:["Suosio kuukausittain ja suunnittain","Suosituimmat reitit nykyisessä karttanäkymässä","Jaa reitti miehistösi kanssa"],image:"route-detail",alt:"Valittuna reitti Sisiliasta Joonian saarille ja sen suosio kunakin kuukautena kumpaankin suuntaan.",coords:"38°12′N · 017°30′E",caption:"Sisilia → Joonian saaret, kuukausittain ja suunnittain"},{id:"route-wind",number:"02",kicker:"Tuuli reitin varrella",title:"Tunne tuuli ennen kuin irrotat köydet.",text:"Jokainen reitti näyttää kuukausittain, millaista tuulta sillä voi odottaa: mistä se puhaltaa, kuinka kovaa, kuinka suuri osa matkasta on vastaista, sivutuulta tai myötäistä ja kuinka usein meri pysyy tyynenä. Sisiliasta Joonian saarille toukokuussa: tuuli luoteesta, 3 boforia, yli puolet matkasta myötäistä.",points:["Vallitseva tuuli ja voimakkuus boforeina joka kuukaudelle","Vastaista, sivutuulta tai myötäistä reitin kurssilla","Aallokko reitin varrella"],image:"route-wind",alt:"Reittikortti Sisiliasta Joonian saarille: vallitseva tuuli, voimakkuus boforeina, tuulen voimakkuus, kurssi ja aallokko joka kuukaudelle, toukokuu valittuna.",coords:"",caption:"Sisilia → Joonian saaret, tuuli toukokuussa",card:!0},{id:"stays",number:"03",kicker:"Veneiden tauot",title:"Missä muut veneet viipyvät.",text:"Mihin miehistöt jättävät veneensä kahdeksi kesäkuukaudeksi, ja missä ne viettävät talven? Veneiden tauot näyttävät satamat ja ankkuripaikat, joissa veneet ovat pitäneet taukoa — muutamasta päivästä yli kuuteen kuukauteen, kausittain.",points:["Suodata tauon pituuden mukaan","Näe, minä kuukausina veneet viipyvät paikassa","Löydä suositut talvisatamat"],image:"stay-detail",alt:"Preveza: tyypillinen tauon pituus ja kuukaudet, joina veneet viipyvät siellä.",coords:"38°57′N · 020°45′E",caption:"Preveza, tauon pituus ja kausi"},{id:"hotspots",number:"04",kicker:"Hotspotit",title:"Löydä rauhallisempi ankkuripaikka.",text:"Missä veneet ruuhkautuvat elokuussa, ja missä on vielä tilaa? Hotspotit näyttää kuukausittain, kuinka vilkas kukin purjehdusalue on. Joonianmeri ja Saroninlahti hehkuvat, kun taas Andros, päivän purjehduksen päässä Ateenasta, pysyy rauhallisena.",points:["Rauhallisesta ruuhkaiseen","Vuoden jokainen kuukausi","Vilkkaimmat ja rauhallisimmat kuukaudet missä tahansa pisteessä"],image:"hotspots",alt:"Kreikan purjehdusalueiden vilkkaus elokuussa: ruuhkaista Joonianmeren saarten ympärillä ja Saroninlahdella, rauhallista Androksen edustalla, pistetarkastelu avoinna.",coords:"38°24′N · 023°36′E",caption:"Hotspotit, Kreikka, elokuu"},{id:"wind",number:"05",kicker:"Tuuli",title:"Kuinka paljon pohjoistuulta on odotettavissa?",text:"Valitse suunta ja kuukausi: heinäkuussa Aigeianmeren keskiosa muuttuu syvän siniseksi. Se on meltemi. Napauta pistettä Mykonoksen lähellä, niin näet tuulen puhaltavan pohjoisesta vähintään 60 %:ssa heinäkuun tunneista.",points:["Voimakkuus ja suunta joka kuukaudelle","Tuuli vuorokaudenajan mukaan","Napauta mitä tahansa pistettä nähdäksesi sen luvut"],image:"wind",alt:"Kuinka usein tuuli puhaltaa pohjoisesta Aigeianmerellä heinäkuussa; pisteen tiedot auki Mykonoksen lähellä.",coords:"37°36′N · 025°00′E",caption:"Pohjoistuuli, Aigeianmeri, heinäkuu"},{id:"waves",number:"06",kicker:"Aallot",title:"Tunne merenkäynti ennen lähtöä.",text:"Kuinka monena päivänä kuukaudessa aallot nousevat 2,5 metriin tai yli? Tammikuussa näkyy selvästi, kuinka laajalle mistral ulottuu Leijonanlahdella.",points:["Tyynestä erittäin kovaan merenkäyntiin","Maininki ja lyhyt, jyrkkä aallokko","Vuoden jokainen kuukausi"],image:"waves",alt:"Kovan aallokon päivät läntisellä Välimerellä tammikuussa.",coords:"41°00′N · 005°00′E",caption:"Kovan aallokon päivät, läntinen Välimeri, tammikuu"},{id:"potential",number:"07",kicker:"Ukkoselle suotuisat olot",title:"Missä ukkoset voivat syntyä.",text:"Kuinka suuren osan ajasta olot suosivat ukkosta, kuukausi kuukaudelta — myös siellä, missä ukkonen olisi voinut kehittyä niinäkin päivinä, kun sitä ei syntynyt.",points:["Vuoden jokainen kuukausi","Napauta mitä tahansa pistettä nähdäksesi sen luvut"],image:"potential",alt:"Ukkoselle suotuisat olot Panaman ympäristössä syyskuussa.",coords:"09°00′N · 079°30′W",caption:"Ukkoselle suotuisat olot, Panama, syyskuu"},{id:"terrain",number:"08",kicker:"Maaston vaikutus",title:"Sama lahti, eri suoja.",text:"Ympäröivät kukkulat voivat suojata ankkuripaikkaa salamoilta. Maaston vaikutus näyttää, kuinka hyvin maasto suojaa lahden kutakin osaa, joten voit valita paremman puolen ennen kuin lasket ankkurin.",points:["Vertaa kohtia saman lahden sisällä","Yhdistä historiallisiin ukkospäiviin"],image:"terrain",alt:"Maaston vaikutus Komižan lahdella Visin saarella Kroatiassa.",coords:"43°02′N · 016°05′E",caption:"Komižan lahti, Vis",markers:[{x:56.9,y:57.69,text:"Ympäröivä maasto suojaa vain vähän.",color:"#762a83"},{x:53.84,y:26.35,text:"Ympäröivä maasto suojaa jonkin verran.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Ympäröivä maasto suojaa enemmän.",color:"#5aae61"}]}],story:{kicker:"Tarinamme",title:"Syntyi läheltä piti -tilanteesta.",text:"Lokakuussa 2024 perheemme purjehti Joonianmerellä, kun salama iski aivan veneemme viereen. Siitä heräsi yksinkertainen kysymys: olemmeko turvallisemmassa paikassa täällä vai lahden toisella puolella? IncusGrid sai alkunsa vastauksena — ja kasvoi kartaksi kaikesta, mitä olisimme halunneet tietää ennen sitä kautta.",more:"Lue koko tarina (englanniksi)",link:`${e}/blog/introducing-incusgrid/`,place:"Igoumenitsa, Kreikka",note:"Täällä idea syntyi"},fromBlog:{kicker:"Blogista",title:"Datatarinoita vesiltä.",all:"Kaikki kirjoitukset",note:"Kirjoitukset englanniksi."},devices:{kicker:"Web & Android",title:"Kannella tai karttapöydän ääressä.",text:"Käytä IncusGridiä missä tahansa selaimessa tai asenna Android-sovellus. Hae purjehdusalueesi ja tutki sitä puhelimella, tabletilla tai kannettavalla.",points:["Selaimessa ilman asennusta","Android-sovellus Google Playssa","Saatavilla 19 kielellä"],web:"Avaa selaimessa",android:"Lataa Google Playsta",phoneAlt:"IncusGridin Android-sovellus, jossa näkyvät veneiden tauot Joonian saarten ympärillä."},final:{title:"Suunnittele seuraava kautesi.",text:"Reitit, veneiden tauot, tuuli, aallot ja salamat — yksi kartta, joka perustuu vuosien todelliseen dataan.",cta:"Avaa kartta"},disclaimerLabel:"Huomio",disclaimer:"IncusGrid näyttää historiallista tietoa suunnittelun tueksi. Se ei ole sääennuste eikä navigoinnin apuväline. Reitit on piirretty kaavamaisesti, ja veneiden tauot on päätelty veneiden sijainti-ilmoitusten katkoista, ei vahvistetuista laituripaikoista. Tarkista aina ajantasaiset ennusteet, viralliset merikartat ja paikalliset olosuhteet ennen kuin lähdet merelle.",footer:{blog:"Blogi",legal:"Oikeudelliset tiedot",privacy:"Tietosuojaseloste",terms:"Käyttöehdot",cookies:"Evästeasetukset",support:"Tuki",madeWith:"Tehty",made:"Portugalissa",englishOnly:"Oikeudelliset sivut ovat englanniksi."}},v={path:"/el",htmlLang:"el",ogLocale:"el_GR",meta:{title:"IncusGrid · Σχεδίασε τη σεζόν σου με πραγματικά δεδομένα",description:"Ιστιοπλοϊκές διαδρομές και παύσεις σκαφών από πραγματικά ταξίδια, συν χρόνια δεδομένων ανέμου, κυμάτων και κεραυνών σε έναν χάρτη. Σχεδίασε τη σεζόν σου.",keywords:"ιστιοπλοΐα, ιστιοπλοϊκές διαδρομές, ιστιοπλοϊκό ταξίδι, αγκυροβόλια, μαρίνα, διαχείμαση σκάφους, μελτέμι, στατιστικά ανέμου, κατάσταση θάλασσας, κύματα, κεραυνοί, καταιγίδες, σχεδιασμός ταξιδιού, σκάφος, ιστιοπλοϊκό"},nav:{routes:"Διαδρομές",stays:"Παύσεις σκαφών",weather:"Καιρός",terrain:"Ανάγλυφο",blog:"Blog",openApp:"Άνοιξε τον χάρτη"},hero:{position:"Sailing intelligence",titleA:"Όχι άλλη μια εφαρμογή καιρού.",titleB:"Όχι άλλο ένα δίκτυο ιστιοπλόων.",lead:"Το IncusGrid μετατρέπει χρόνια δεδομένων στην τοπική γνώση που χρειάζεται κάθε πλήρωμα πριν λύσει κάβους: πραγματικές κινήσεις σκαφών, άνεμος, κύματα και κεραυνοί σε έναν χάρτη — για να σχεδιάσεις το επόμενο πέρασμά σου με τη συλλογική γνώση χιλιάδων ιστιοπλόων.",ctaApp:"Άνοιξε τον χάρτη",ctaAndroid:"Εφαρμογή Android",heroAlt:"Ιστιοπλοϊκές διαδρομές στην Καραϊβική, από την Ισπανιόλα ως τις Μικρές Αντίλλες και τις ακτές της Νότιας Αμερικής, σχεδιασμένες από πραγματικά ταξίδια ιστιοπλοϊκών σκαφών.",heroCaption:"Ιστιοπλοϊκές διαδρομές, Καραϊβική Θάλασσα · όλοι οι μήνες",notes:[{label:"Σκάφη",value:"Χιλιάδες"},{label:"Κινήσεις",value:"Εκατομμύρια"},{label:"Πτώσεις κεραυνών",value:"Δισεκατομμύρια"},{label:"Κάλυψη",value:"Παγκόσμια"}]},contrast:{kicker:"Δεν είναι πρόγνωση",title:"Η πρόγνωση σου λέει τι φέρνει το αύριο. Το IncusGrid σου δείχνει τη σεζόν.",text:"Ποιο πέρασμα κάνουν τα πληρώματα τον Ιούνιο; Πού ξεχειμωνιάζουν τα σκάφη; Ποιος μήνας φέρνει το μελτέμι, και ποια πλευρά του κόλπου προστατεύεται καλύτερα από τους κεραυνούς; Απαντήσεις που φαίνονται μόνο όταν κοιτάς πολλά χρόνια μαζί."},chapters:[{id:"routes",number:"01",kicker:"Ιστιοπλοϊκές διαδρομές",title:"Σχεδίασε περάσματα με την εμπειρία χιλιάδων πληρωμάτων.",text:"Χιλιάδες πραγματικά ταξίδια δείχνουν πότε ένα πέρασμα έχει νόημα, προς ποια κατεύθυνση, και από πού ξεκινούν και πού φτάνουν τα πληρώματα. Οι επικρατούντες άνεμοι, καλά σημεία για να περιμένεις ένα καιρικό παράθυρο και μια ασφαλής άφιξη μετά από μια νύχτα στη θάλασσα είναι ήδη μέσα. Από τη Σικελία προς τα Ιόνια νησιά, για παράδειγμα, τα περισσότερα σκάφη πλέουν ανατολικά τον Μάιο και τον Ιούνιο και επιστρέφουν τον Σεπτέμβριο.",points:["Δημοτικότητα ανά μήνα και κατεύθυνση","Οι πιο δημοφιλείς διαδρομές στην τρέχουσα προβολή του χάρτη","Μοιράσου μια διαδρομή με το πλήρωμά σου"],image:"route-detail",alt:"Επιλεγμένη η διαδρομή από τη Σικελία προς τα Ιόνια νησιά, με τη δημοτικότητά της ανά μήνα και κατεύθυνση.",coords:"38°12′N · 017°30′E",caption:"Σικελία → Ιόνια νησιά, ανά μήνα και κατεύθυνση"},{id:"route-wind",number:"02",kicker:"Ο άνεμος στη διαδρομή",title:"Μάθε τον άνεμο πριν λύσεις κάβους.",text:"Κάθε διαδρομή δείχνει τον άνεμο που μπορείς να περιμένεις, μήνα με μήνα: από πού φυσά, πόσο δυνατά, τι μέρος του περάσματος πλέεις όρτσα, τραβέρσο ή πρύμα, και πόσο συχνά η θάλασσα μένει ήρεμη. Από τη Σικελία προς τα Ιόνια νησιά τον Μάιο: βορειοδυτικός άνεμος, 3 Μποφόρ, πάνω από τη μισή διαδρομή πρύμα.",points:["Επικρατών άνεμος και ένταση σε Μποφόρ για κάθε μήνα","Όρτσα, τραβέρσο ή πρύμα στην πορεία της διαδρομής","Κατάσταση της θάλασσας κατά μήκος της διαδρομής"],image:"route-wind",alt:"Η κάρτα της διαδρομής από τη Σικελία προς τα Ιόνια νησιά: επικρατών άνεμος, ένταση σε Μποφόρ, ένταση ανέμου, πλεύση και κατάσταση της θάλασσας για κάθε μήνα, με επιλεγμένο τον Μάιο.",coords:"",caption:"Σικελία → Ιόνια νησιά, ο άνεμος τον Μάιο",card:!0},{id:"stays",number:"03",kicker:"Παύσεις σκαφών",title:"Πού μένουν τα άλλα σκάφη.",text:"Πού αφήνουν τα πληρώματα το σκάφος τους για δύο μήνες το καλοκαίρι, και πού περνούν τον χειμώνα; Οι παύσεις σκαφών δείχνουν τα λιμάνια και τα αγκυροβόλια όπου σταμάτησαν σκάφη — από λίγες μέρες έως πάνω από έξι μήνες, ανά εποχή.",points:["Φίλτρο ανά διάρκεια παραμονής","Δες ποιους μήνες μένουν σκάφη σε ένα σημείο","Βρες δημοφιλή λιμάνια διαχείμασης"],image:"stay-detail",alt:"Πρέβεζα: τυπική διάρκεια παραμονής και οι μήνες κατά τους οποίους μένουν εκεί σκάφη.",coords:"38°57′N · 020°45′E",caption:"Πρέβεζα, διάρκεια παραμονής και εποχή"},{id:"hotspots",number:"04",kicker:"Hotspots",title:"Βρείτε το πιο ήσυχο αγκυροβόλι.",text:"Πού συνωστίζονται τα σκάφη τον Αύγουστο και πού υπάρχει ακόμα χώρος; Τα Hotspots δείχνουν, μήνα με μήνα, πόσο πολυσύχναστη είναι κάθε ιστιοπλοϊκή περιοχή. Το Ιόνιο και ο Σαρωνικός λάμπουν, ενώ η Άνδρος, μια μέρα πλεύση από την Αθήνα, μένει ήσυχη.",points:["Από ήσυχο έως πολυσύχναστο","Κάθε μήνα του χρόνου","Οι πιο πολυσύχναστοι και οι πιο ήσυχοι μήνες σε κάθε σημείο"],image:"hotspots",alt:"Πόσο πολυσύχναστες είναι οι ελληνικές ιστιοπλοϊκές περιοχές τον Αύγουστο: γεμάτες γύρω από τα Ιόνια νησιά και στον Σαρωνικό, ήσυχες ανοιχτά της Άνδρου, με ανοιχτό τον επιθεωρητή σημείου.",coords:"38°24′N · 023°36′E",caption:"Hotspots, Ελλάδα, Αύγουστος"},{id:"wind",number:"05",kicker:"Άνεμος",title:"Πόσο βοριά να περιμένεις;",text:"Διάλεξε κατεύθυνση και μήνα: τον Ιούλιο το κεντρικό Αιγαίο βάφεται βαθύ μπλε. Αυτό είναι το μελτέμι. Πάτησε σε ένα σημείο κοντά στη Μύκονο και θα δεις ότι τον Ιούλιο φυσάει από βορρά στο 60% των ωρών ή και παραπάνω.",points:["Ένταση και κατεύθυνση για κάθε μήνα","Άνεμος ανά ώρα της ημέρας","Πάτησε σε ένα σημείο για τις τιμές του"],image:"wind",alt:"Πόσο συχνά φυσάει βοριάς στο Αιγαίο τον Ιούλιο, με ανοιχτή την επιθεώρηση σημείου κοντά στη Μύκονο.",coords:"37°36′N · 025°00′E",caption:"Βόρειος άνεμος, Αιγαίο, Ιούλιος"},{id:"waves",number:"06",kicker:"Κύματα",title:"Μάθε τη θάλασσα πριν ξεκινήσεις.",text:"Πόσες μέρες τον μήνα φέρνουν κύματα 2,5 m και πάνω; Τον Ιανουάριο φαίνεται καθαρά πόσο μακριά φτάνει ο μιστράλ πάνω από τον Κόλπο του Λέοντος.",points:["Από ήρεμη έως πολύ τρικυμιώδη θάλασσα","Φουσκοθαλασσιά και κοντός, απότομος κυματισμός","Κάθε μήνας του χρόνου"],image:"waves",alt:"Ημέρες τρικυμίας στη δυτική Μεσόγειο τον Ιανουάριο.",coords:"41°00′N · 005°00′E",caption:"Ημέρες τρικυμίας, δυτική Μεσόγειος, Ιανουάριος"},{id:"potential",number:"07",kicker:"Συνθήκες καταιγίδων",title:"Πού μπορούν να σχηματιστούν καταιγίδες.",text:"Το ποσοστό του χρόνου με συνθήκες ευνοϊκές για καταιγίδες, μήνα με μήνα — ακόμη και εκεί όπου θα μπορούσαν να σχηματιστούν καταιγίδες τις μέρες που τελικά δεν σχηματίστηκε καμία.",points:["Κάθε μήνας του χρόνου","Πάτησε σε ένα σημείο για τις τιμές του"],image:"potential",alt:"Συνθήκες καταιγίδων γύρω από τον Παναμά τον Σεπτέμβριο.",coords:"09°00′N · 079°30′W",caption:"Συνθήκες καταιγίδων, Παναμάς, Σεπτέμβριος"},{id:"terrain",number:"08",kicker:"Έκθεση λόγω αναγλύφου",title:"Ίδιος κόλπος, άλλη θωράκιση.",text:"Οι γύρω λόφοι μπορούν να θωρακίσουν ένα αγκυροβόλιο από τους κεραυνούς. Η έκθεση λόγω αναγλύφου δείχνει πόσο καλά προστατεύει το ανάγλυφο κάθε σημείο ενός κόλπου, για να διαλέξεις την καλύτερη πλευρά πριν ρίξεις άγκυρα.",points:["Σύγκρινε σημεία μέσα στον ίδιο κόλπο","Συνδύασέ την με τις ιστορικές ημέρες καταιγίδας"],image:"terrain",alt:"Έκθεση λόγω αναγλύφου στον κόλπο της Κόμιζα στο Βις της Κροατίας.",coords:"43°02′N · 016°05′E",caption:"Κόλπος της Κόμιζα, Βις",markers:[{x:56.9,y:57.69,text:"Μικρή θωράκιση από το γύρω ανάγλυφο.",color:"#762a83"},{x:53.84,y:26.35,text:"Κάποια θωράκιση από το γύρω ανάγλυφο.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Μεγαλύτερη θωράκιση από το γύρω ανάγλυφο.",color:"#5aae61"}]}],story:{kicker:"Η ιστορία μας",title:"Γεννήθηκε από μια στιγμή τρόμου.",text:"Τον Οκτώβριο του 2024 η οικογένειά μας έπλεε στο Ιόνιο, όταν ένας κεραυνός έπεσε ακριβώς δίπλα στο σκάφος μας. Εκείνη η στιγμή γέννησε ένα απλό ερώτημα: είμαστε πιο ασφαλείς εδώ ή στην άλλη πλευρά του κόλπου; Το IncusGrid ξεκίνησε ως η απάντηση — και έγινε ένας χάρτης με όλα όσα θα θέλαμε να ξέρουμε πριν από εκείνη τη σεζόν.",more:"Διάβασε όλη την ιστορία (στα αγγλικά)",link:`${e}/blog/introducing-incusgrid/`,place:"Ηγουμενίτσα, Ελλάδα",note:"Εκεί γεννήθηκε η ιδέα"},fromBlog:{kicker:"Από το blog",title:"Ιστορίες δεδομένων από τη θάλασσα.",all:"Όλα τα άρθρα",note:"Άρθρα στα αγγλικά."},devices:{kicker:"Web & Android",title:"Στο κατάστρωμα ή στο τραπέζι χαρτών.",text:"Χρησιμοποίησε το IncusGrid σε οποιονδήποτε browser ή εγκατάστησε την εφαρμογή Android. Αναζήτησε την περιοχή όπου πλέεις και εξερεύνησέ την σε κινητό, tablet ή laptop.",points:["Χωρίς εγκατάσταση στον browser","Εφαρμογή Android στο Google Play","Διαθέσιμο σε 19 γλώσσες"],web:"Άνοιξε στον browser",android:"Κατέβασέ το από το Google Play",phoneAlt:"Η εφαρμογή Android του IncusGrid με παύσεις σκαφών γύρω από τα Ιόνια νησιά."},final:{title:"Σχεδίασε την επόμενη σεζόν σου.",text:"Διαδρομές, παύσεις σκαφών, άνεμος, κύματα και κεραυνοί — ένας χάρτης, φτιαγμένος από πολλά χρόνια πραγματικών δεδομένων.",cta:"Άνοιξε τον χάρτη"},disclaimerLabel:"Προσοχή",disclaimer:"Το IncusGrid δείχνει ιστορικά μοτίβα για τον σχεδιασμό. Δεν είναι πρόγνωση καιρού ούτε βοήθημα ναυσιπλοΐας. Οι διαδρομές είναι σχηματικές, και οι παύσεις σκαφών προκύπτουν από διακοπές στις αναφορές θέσης, όχι από επιβεβαιωμένες θέσεις ελλιμενισμού. Πριν βγεις στη θάλασσα, έλεγξε πάντα τις τρέχουσες προγνώσεις, τους επίσημους ναυτικούς χάρτες και τις τοπικές συνθήκες.",footer:{blog:"Blog",legal:"Νομικές πληροφορίες",privacy:"Πολιτική απορρήτου",terms:"Όροι χρήσης",cookies:"Ρυθμίσεις cookies",support:"Υποστήριξη",madeWith:"Φτιαγμένο με",made:"στην Πορτογαλία",englishOnly:"Οι νομικές σελίδες είναι στα αγγλικά."}},h={path:"/hr",htmlLang:"hr",ogLocale:"hr_HR",meta:{title:"IncusGrid · Planiraj sezonu jedrenja uz stvarne podatke",description:"Jedriličarske rute i stanke brodova iz stvarnih plovidbi, uz godine podataka o vjetru, valovima i munjama na jednoj karti. Planiraj sljedeću sezonu.",keywords:"jedriličarske rute, krstarenje jedrilicom, sidrište, marina, zimovanje broda, statistika vjetra, stanje mora, valovi, munje, grmljavina, planiranje plovidbe, jedrilica, nautika, jedrenje Sredozemljem"},nav:{routes:"Rute",stays:"Stanke brodova",weather:"Vrijeme",terrain:"Teren",blog:"Blog",openApp:"Otvori kartu"},hero:{position:"Sailing intelligence",titleA:"Nije još jedna aplikacija za vrijeme.",titleB:"Nije još jedna mreža nautičara.",lead:"IncusGrid pretvara godine podataka u lokalno znanje koje svakoj posadi treba prije isplovljavanja: stvarna kretanja brodova, vjetar, valovi i munje na jednoj karti — da sljedeću plovidbu možeš planirati uz zajedničko znanje tisuća jedriličara.",ctaApp:"Otvori kartu",ctaAndroid:"Android aplikacija",heroAlt:"Jedriličarske rute Karipskim morem, od Hispaniole do Malih Antila i obale Južne Amerike, iscrtane prema stvarnim plovidbama brodova na krstarenju.",heroCaption:"Jedriličarske rute, Karipsko more · svi mjeseci",notes:[{label:"Brodovi",value:"Tisuće"},{label:"Kretanja",value:"Milijuni"},{label:"Udari munja",value:"Milijarde"},{label:"Pokrivenost",value:"Cijeli svijet"}]},contrast:{kicker:"Nije prognoza",title:"Prognoza ti kaže što donosi sutra. IncusGrid ti pokazuje sezonu.",text:"Kojim prijelazom posade plove u lipnju? Gdje brodovi zimuju? Koji mjesec donosi meltemi, i koja je strana uvale bolje zaštićena od munja? Odgovori koji se pokažu tek kad gledaš mnogo godina odjednom."},chapters:[{id:"routes",number:"01",kicker:"Jedriličarske rute",title:"Planiraj prijelaze s iskustvom tisuća posada.",text:"Tisuće stvarnih plovidbi pokazuju kada prijelaz ima smisla, u kojem smjeru, i gdje posade isplovljavaju i stižu. Prevladavajući vjetrovi, dobra mjesta za čekanje vremenskog prozora i sigurno pristajanje nakon noći na moru već su ugrađeni. Od Sicilije do Jonskih otoka, na primjer, većina brodova u svibnju i lipnju plovi na istok, a u rujnu se vraća.",points:["Popularnost po mjesecu i smjeru","Najpopularnije rute u trenutnom prikazu karte","Podijeli rutu sa svojom posadom"],image:"route-detail",alt:"Odabrana ruta od Sicilije do Jonskih otoka, s popularnošću u svakom mjesecu i smjeru.",coords:"38°12′N · 017°30′E",caption:"Sicilija → Jonski otoci, po mjesecu i smjeru"},{id:"route-wind",number:"02",kicker:"Vjetar duž rute",title:"Upoznaj vjetar prije nego što isploviš.",text:"Svaka ruta pokazuje vjetar koji na njoj možeš očekivati, mjesec po mjesec: odakle puše, koliko jako, koliki dio prijelaza ploviš u orcu, s bočnim ili krmenim vjetrom i koliko je često more mirno. Od Sicilije do Jonskih otoka u svibnju: vjetar sa sjeverozapada, 3 Bf, više od pola puta s krmenim vjetrom.",points:["Prevladavajući vjetar i jačina u Beaufortima za svaki mjesec","U orcu, s bočnim ili krmenim vjetrom na kursu rute","Stanje mora duž rute"],image:"route-wind",alt:"Kartica rute od Sicilije do Jonskih otoka: prevladavajući vjetar, jačina u Beaufortima, jačina vjetra, kurs i stanje mora za svaki mjesec, s odabranim svibnjem.",coords:"",caption:"Sicilija → Jonski otoci, vjetar u svibnju",card:!0},{id:"stays",number:"03",kicker:"Stanke brodova",title:"Gdje drugi brodovi ostaju.",text:"Gdje posade ostavljaju brod na dva ljetna mjeseca, a gdje provode zimu? Stanke brodova pokazuju luke i sidrišta u kojima su brodovi napravili stanku — od nekoliko dana do više od šest mjeseci, po sezoni.",points:["Filtriraj po trajanju stanke","Pogledaj u kojim mjesecima brodovi ostaju na nekom mjestu","Pronađi popularne luke za zimovanje"],image:"stay-detail",alt:"Preveza: uobičajeno trajanje stanke i mjeseci u kojima brodovi ondje ostaju.",coords:"38°57′N · 020°45′E",caption:"Preveza, trajanje stanke i sezona"},{id:"hotspots",number:"04",kicker:"Hotspotovi",title:"Pronađite mirnije sidrište.",text:"Gdje se brodovi gužvaju u kolovozu, a gdje još ima mjesta? Hotspotovi iz mjeseca u mjesec pokazuju koliko je koje nautičko područje prometno. Jonsko more i Saronski zaljev svijetle, dok Andros, dan plovidbe od Atene, ostaje miran.",points:["Od mirnog do prepunog","Svaki mjesec u godini","Najprometniji i najmirniji mjeseci na svakoj točki"],image:"hotspots",alt:"Koliko su grčka nautička područja prometna u kolovozu: gužva oko Jonskih otoka i u Saronskom zaljevu, mirno uz Andros, s otvorenim inspektorom točke.",coords:"38°24′N · 023°36′E",caption:"Hotspotovi, Grčka, kolovoz"},{id:"wind",number:"05",kicker:"Vjetar",title:"Koliko sjevernog vjetra možeš očekivati?",text:"Odaberi smjer i mjesec: u srpnju središnji Egej postaje tamnoplav. To je meltemi. Dodirni točku kod Mikonosa i vidjet ćeš da u srpnju vjetar puše sa sjevera u 60 % svih sati ili više.",points:["Jačina i smjer za svaki mjesec","Vjetar po dobu dana","Dodirni bilo koju točku za njezine vrijednosti"],image:"wind",alt:"Koliko često u srpnju vjetar puše sa sjevera u Egejskom moru, s otvorenim detaljima točke kod Mikonosa.",coords:"37°36′N · 025°00′E",caption:"Vjetar sa sjevera, Egejsko more, srpanj"},{id:"waves",number:"06",kicker:"Valovi",title:"Upoznaj stanje mora prije isplovljavanja.",text:"Koliko dana u mjesecu donosi valove od 2,5 m ili više? U siječnju se jasno vidi dokle mistral seže preko Lionskog zaljeva.",points:["Od mirnog do vrlo uzburkanog mora","Mrtvo more i kratko, strmo more","Svaki mjesec u godini"],image:"waves",alt:"Dani s uzburkanim morem u zapadnom Sredozemlju u siječnju.",coords:"41°00′N · 005°00′E",caption:"Dani uzburkanog mora, zapadno Sredozemlje, siječanj"},{id:"potential",number:"07",kicker:"Uvjeti za grmljavinu",title:"Gdje se grmljavina može razviti.",text:"Udio vremena s uvjetima povoljnima za grmljavinu, mjesec po mjesec — uključujući mjesta gdje se nevrijeme moglo razviti i u danima kad ga nije bilo.",points:["Svaki mjesec u godini","Dodirni bilo koju točku za njezine vrijednosti"],image:"potential",alt:"Uvjeti za grmljavinu oko Paname u rujnu.",coords:"09°00′N · 079°30′W",caption:"Uvjeti za grmljavinu, Panama, rujan"},{id:"terrain",number:"08",kicker:"Izloženost terenu",title:"Ista uvala, drukčiji zaklon.",text:"Okolna brda mogu zakloniti sidrište od munja. Izloženost terenu pokazuje koliko dobro teren štiti svaki dio uvale, pa možeš odabrati bolju stranu prije nego što baciš sidro.",points:["Usporedi mjesta unutar iste uvale","Kombiniraj s povijesnim danima s grmljavinom"],image:"terrain",alt:"Izloženost terenu u uvali Komiža na Visu.",coords:"43°02′N · 016°05′E",caption:"Uvala Komiža, Vis",markers:[{x:56.9,y:57.69,text:"Malo zaklanjanja okolnim terenom.",color:"#762a83"},{x:53.84,y:26.35,text:"Djelomično zaklanjanje okolnim terenom.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Veće zaklanjanje okolnim terenom.",color:"#5aae61"}]}],story:{kicker:"Naša priča",title:"Nastalo iz trenutka straha.",text:"U listopadu 2024. naša je obitelj plovila Jonskim morem kad je munja udarila tik uz naš brod. Taj je trenutak otvorio jednostavno pitanje: jesmo li sigurniji ovdje ili na drugoj strani uvale? IncusGrid je počeo kao odgovor — i izrastao u kartu svega što bismo voljeli da smo znali prije te sezone.",more:"Pročitaj cijelu priču (na engleskom)",link:`${e}/blog/introducing-incusgrid/`,place:"Igumenica, Grčka",note:"Gdje je ideja nastala"},fromBlog:{kicker:"S bloga",title:"Priče iz podataka, s mora.",all:"Svi članci",note:"Članci na engleskom."},devices:{kicker:"Web & Android",title:"Na palubi ili za kartografskim stolom.",text:"Koristi IncusGrid u bilo kojem pregledniku ili instaliraj Android aplikaciju. Pronađi svoje područje plovidbe i istražuj ga na mobitelu, tabletu ili laptopu.",points:["U pregledniku bez instalacije","Android aplikacija na Google Playu","Dostupno na 19 jezika"],web:"Otvori u pregledniku",android:"Preuzmi na Google Playu",phoneAlt:"IncusGrid Android aplikacija sa stankama brodova oko Jonskih otoka."},final:{title:"Planiraj sljedeću sezonu.",text:"Rute, stanke brodova, vjetar, valovi i munje — jedna karta, izgrađena na mnogo godina stvarnih podataka.",cta:"Otvori kartu"},disclaimerLabel:"Napomena",disclaimer:"IncusGrid prikazuje povijesne obrasce za planiranje. Nije vremenska prognoza ni navigacijsko pomagalo. Rute su ucrtane shematski. Stanke brodova izvedene su iz prekida u javljanju položaja brodova, a ne iz potvrđenih vezova. Prije isplovljavanja uvijek provjeri aktualne prognoze, službene pomorske karte i lokalne uvjete.",footer:{blog:"Blog",legal:"Impresum",privacy:"Pravila privatnosti",terms:"Uvjeti korištenja",cookies:"Postavke kolačića",support:"Podrška",madeWith:"Napravljeno s",made:"u Portugalu",englishOnly:"Pravne stranice su na engleskom."}},b={path:"/tr",htmlLang:"tr",ogLocale:"tr_TR",meta:{title:"IncusGrid · Yelken sezonunu gerçek verilerle planla",description:"Gerçek seyirlerden yelken rotaları ve tekne molaları, artı yıllara yayılan rüzgâr, dalga ve yıldırım verileri tek haritada. Sonraki sezonunu planla.",keywords:"yelken rotaları, yelkenli gezi, mavi yolculuk, koy, demir yeri, marina, kışlama, rüzgâr istatistiği, meltem, dalga, deniz durumu, yıldırım, fırtına, seyir planlama, yelkenli, tekne"},nav:{routes:"Rotalar",stays:"Tekne molaları",weather:"Hava",terrain:"Arazi",blog:"Blog",openApp:"Haritayı aç"},hero:{position:"Sailing intelligence",titleA:"Bir hava durumu uygulaması daha değil.",titleB:"Bir denizci ağı daha değil.",lead:"IncusGrid, yıllara yayılan verileri her mürettebatın demir almadan önce bilmesi gereken yerel bilgiye dönüştürür: gerçek tekne hareketleri, rüzgâr, dalgalar ve yıldırımlar tek bir haritada — böylece bir sonraki geçişini binlerce denizcinin ortak bilgisiyle planlayabilirsin.",ctaApp:"Haritayı aç",ctaAndroid:"Android uygulaması",heroAlt:"Karayip Denizi’nde, Hispaniola’dan Küçük Antiller’e ve Güney Amerika kıyılarına uzanan, gezi teknelerinin gerçek seyirlerinden çizilmiş yelken rotaları.",heroCaption:"Yelken rotaları, Karayip Denizi · tüm aylar",notes:[{label:"Tekne",value:"Binlerce"},{label:"Hareket",value:"Milyonlarca"},{label:"Yıldırım düşmesi",value:"Milyarlarca"},{label:"Kapsam",value:"Dünya geneli"}]},contrast:{kicker:"Hava tahmini değil",title:"Hava tahmini sana yarını anlatır. IncusGrid ise sezonu.",text:"Mürettebatlar haziranda hangi geçişi yapıyor? Tekneler kışı nerede geçiriyor? Meltem hangi ay başlıyor, koyun hangi tarafı yıldırıma karşı daha korunaklı? Bu cevaplar ancak birçok yıla birden baktığında ortaya çıkar."},chapters:[{id:"routes",number:"01",kicker:"Yelken rotaları",title:"Geçişleri binlerce mürettebatın deneyimiyle planla.",text:"Binlerce gerçek seyir, bir geçişin ne zaman mantıklı olduğunu, hangi yönde yapıldığını ve mürettebatların nereden ayrılıp nereye vardığını gösterir. Hâkim rüzgârlar, hava penceresi beklemek için iyi yerler ve denizde geçen bir gecenin ardından güvenli bir varış noktası zaten bu verinin içinde. Örneğin Sicilya’dan İyon Adaları’na teknelerin çoğu mayıs ve haziranda doğuya gider, eylülde geri döner.",points:["Aya ve yöne göre popülerlik","Harita görünümündeki en popüler rotalar","Bir rotayı mürettebatınla paylaş"],image:"route-detail",alt:"Sicilya’dan İyon Adaları’na giden rota seçili; her ay ve yöndeki popülerliğiyle birlikte.",coords:"38°12′N · 017°30′E",caption:"Sicilya → İyon Adaları, aya ve yöne göre"},{id:"route-wind",number:"02",kicker:"Rota boyunca rüzgâr",title:"Halatları çözmeden önce rüzgârı tanı.",text:"Her rota, ay ay bekleyebileceğin rüzgârı gösterir: nereden estiğini, ne kadar sert estiğini, geçişin ne kadarını orsa, apaz veya pupa seyirde geçireceğini ve denizin ne sıklıkla sakin kaldığını. Mayısta Sicilya’dan İyon Adaları’na: kuzeybatıdan rüzgâr, 3 Beaufort, yolun yarısından fazlası pupa.",points:["Her ay için hâkim rüzgâr ve Beaufort kuvveti","Rotanın yönünde orsa, apaz veya pupa","Rota boyunca deniz durumu"],image:"route-wind",alt:"Sicilya’dan İyon Adaları’na rota kartı: her ay için hâkim rüzgâr, Beaufort kuvveti, rüzgâr kuvveti, seyir ve deniz durumu; mayıs seçili.",coords:"",caption:"Sicilya → İyon Adaları, mayısta rüzgâr",card:!0},{id:"stays",number:"03",kicker:"Tekne molaları",title:"Diğer tekneler nerede kalıyor?",text:"Mürettebatlar yazın teknelerini iki aylığına nerede bırakıyor, kışı nerede geçiriyor? Tekne molaları, teknelerin birkaç günden altı aydan uzun sürelere kadar mola verdiği limanları ve demir yerlerini mevsime göre gösterir.",points:["Kalış süresine göre filtrele","Teknelerin bir yerde hangi aylarda kaldığını gör","Popüler kışlama limanlarını keşfet"],image:"stay-detail",alt:"Preveze: tipik kalış süresi ve teknelerin orada kaldığı aylar.",coords:"38°57′N · 020°45′E",caption:"Preveze, kalış süresi ve mevsim"},{id:"hotspots",number:"04",kicker:"Hotspotlar",title:"Daha sakin koyu bulun.",text:"Ağustosta tekneler nerede kalabalıklaşıyor, nerede hâlâ yer var? Hotspotlar her seyir bölgesinin ne kadar yoğun olduğunu ay ay gösterir. İyon Denizi ve Saronik Körfezi parlarken Atina’ya bir günlük seyir mesafesindeki Andros sakin kalır.",points:["Sakinden kalabalığa","Yılın her ayı","Her noktada en yoğun ve en sakin aylar"],image:"hotspots",alt:"Yunan seyir bölgelerinin ağustostaki yoğunluğu: İyon Adaları çevresinde ve Saronik Körfezi’nde kalabalık, Andros açıklarında sakin, nokta denetçisi açık.",coords:"38°24′N · 023°36′E",caption:"Hotspotlar, Yunanistan, ağustos"},{id:"wind",number:"05",kicker:"Rüzgâr",title:"Ne kadar kuzey rüzgârı beklemelisin?",text:"Bir yön ve bir ay seç: temmuzda Ege’nin ortası koyu maviye döner. İşte meltem bu. Mikonos yakınında bir noktaya dokun; temmuzda rüzgârın saatlerin %60’ında ya da daha fazlasında kuzeyden estiğini görürsün.",points:["Her ay için kuvvet ve yön","Günün saatine göre rüzgâr","Değerlerini görmek için herhangi bir noktaya dokun"],image:"wind",alt:"Temmuzda Ege Denizi’nde rüzgârın ne sıklıkla kuzeyden estiği; Mikonos yakınında nokta incelemesi açık.",coords:"37°36′N · 025°00′E",caption:"Kuzeyden rüzgâr, Ege Denizi, temmuz"},{id:"waves",number:"06",kicker:"Dalgalar",title:"Yola çıkmadan denizi tanı.",text:"Ayda kaç gün 2,5 m ve üzeri dalga getiriyor? Ocakta Mistral’in Lion Körfezi üzerinden ne kadar uzağa ulaştığı açıkça görülür.",points:["Sakin denizden çok dalgalı denize","Ölü dalga ve kısa, dik dalgalar","Yılın her ayı"],image:"waves",alt:"Ocakta Batı Akdeniz’de dalgalı geçen günler.",coords:"41°00′N · 005°00′E",caption:"Dalgalı günler, Batı Akdeniz, ocak"},{id:"potential",number:"07",kicker:"Gök gürültülü fırtına potansiyeli",title:"Fırtınaların oluşabileceği yerler.",text:"Fırtınaya elverişli koşulların görüldüğü zaman payı, ay ay — hiç fırtına oluşmayan günlerde bile fırtınanın oluşabileceği yerler dahil.",points:["Yılın her ayı","Değerlerini görmek için herhangi bir noktaya dokun"],image:"potential",alt:"Eylülde Panama çevresinde gök gürültülü fırtına potansiyeli.",coords:"09°00′N · 079°30′W",caption:"Gök gürültülü fırtına potansiyeli, Panama, eylül"},{id:"terrain",number:"08",kicker:"Araziye bağlı maruziyet",title:"Aynı koy, farklı perdeleme.",text:"Çevredeki tepeler bir demir yerini yıldırıma karşı perdeleyebilir. Araziye bağlı maruziyet, arazinin bir koyun her bölümünü ne kadar iyi koruduğunu gösterir; böylece demir atmadan önce daha iyi tarafı seçebilirsin.",points:["Aynı koy içindeki noktaları karşılaştır","Geçmişteki fırtınalı günlerle birlikte değerlendir"],image:"terrain",alt:"Hırvatistan’da, Vis adasındaki Komiža koyunda araziye bağlı maruziyet.",coords:"43°02′N · 016°05′E",caption:"Komiža koyu, Vis",markers:[{x:56.9,y:57.69,text:"Çevredeki araziden az perdeleme.",color:"#762a83"},{x:53.84,y:26.35,text:"Çevredeki araziden bir miktar perdeleme.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Çevredeki araziden daha güçlü perdeleme.",color:"#5aae61"}]}],story:{kicker:"Hikâyemiz",title:"Kıl payı atlatılan bir anda doğdu.",text:"Ekim 2024’te ailemizle İyon Denizi’nde seyrederken teknemizin hemen yanına yıldırım düştü. O an basit bir soru doğurdu: Burada mı daha güvendeyiz, yoksa koyun öbür tarafında mı? IncusGrid bu sorunun cevabı olarak başladı — ve o sezondan önce bilmek isteyeceğimiz her şeyin haritasına dönüştü.",more:"Hikâyenin tamamını oku (İngilizce)",link:`${e}/blog/introducing-incusgrid/`,place:"İgumenitsa, Yunanistan",note:"Fikrin doğduğu yer"},fromBlog:{kicker:"Blogdan",title:"Denizden veri hikâyeleri.",all:"Tüm yazılar",note:"Yazılar İngilizce."},devices:{kicker:"Web & Android",title:"Güvertede ya da harita masasında.",text:"IncusGrid’i herhangi bir tarayıcıda kullan ya da Android uygulamasını yükle. Seyir bölgeni ara ve telefonda, tablette veya dizüstü bilgisayarda keşfet.",points:["Tarayıcıda kurulum gerektirmez","Google Play’de Android uygulaması","19 dilde kullanılabilir"],web:"Tarayıcıda aç",android:"Google Play’den indir",phoneAlt:"İyon Adaları çevresindeki tekne molalarını gösteren IncusGrid Android uygulaması."},final:{title:"Bir sonraki sezonunu planla.",text:"Rotalar, tekne molaları, rüzgâr, dalgalar ve yıldırımlar — uzun yılların gerçek verisiyle oluşturulmuş tek bir harita.",cta:"Haritayı aç"},disclaimerLabel:"Dikkat",disclaimer:"IncusGrid planlama için geçmiş örüntüleri gösterir. Hava tahmini ya da seyir yardımcısı değildir. Rotalar şematik olarak çizilmiştir; tekne molaları ise doğrulanmış bağlama yerlerinden değil, tekne bildirimlerindeki aralardan çıkarılır. Denize açılmadan önce her zaman güncel tahminleri, resmi deniz haritalarını ve yerel koşulları kontrol et.",footer:{blog:"Blog",legal:"Yasal Bilgiler",privacy:"Gizlilik Politikası",terms:"Kullanım Koşulları",cookies:"Çerez Ayarları",support:"Destek",madeWith:"Portekiz’de",made:"ile yapıldı",englishOnly:"Yasal sayfalar İngilizcedir."}},y={path:"/pt-br",htmlLang:"pt-BR",ogLocale:"pt_BR",meta:{title:"IncusGrid · Planeje sua temporada de vela com dados reais",description:"Rotas de navegação e pausas dos barcos de travessias reais, mais anos de dados de vento, ondas e raios em um só mapa. Planeje sua próxima temporada.",keywords:"rotas de navegação, rotas de veleiro, velejar, cruzeiro à vela, vida a bordo, ancoradouro, fundeadouro, marina, invernagem, estatísticas de vento, estado do mar, ondas, raios, tempestades, planejamento de velejada, veleiro"},nav:{routes:"Rotas",stays:"Pausas dos barcos",weather:"Tempo",terrain:"Terreno",blog:"Blog",openApp:"Abrir o mapa"},hero:{position:"Sailing intelligence",titleA:"Não é mais um app de previsão do tempo.",titleB:"Não é mais uma rede de velejadores.",lead:"O IncusGrid transforma anos de dados no conhecimento local de que toda tripulação precisa antes de soltar as amarras: movimentos reais de barcos, vento, ondas e raios em um só mapa — para você planejar sua próxima travessia com o conhecimento coletivo de milhares de velejadores.",ctaApp:"Abrir o mapa",ctaAndroid:"App para Android",heroAlt:"Rotas de navegação pelo Mar do Caribe, de Hispaniola às Pequenas Antilhas e à costa da América do Sul, traçadas a partir de travessias reais de veleiros de cruzeiro.",heroCaption:"Rotas de navegação, Mar do Caribe · todos os meses",notes:[{label:"Barcos",value:"Milhares"},{label:"Movimentos",value:"Milhões"},{label:"Descargas de raios",value:"Bilhões"},{label:"Cobertura",value:"Mundial"}]},contrast:{kicker:"Não é previsão",title:"A previsão fala de amanhã. O IncusGrid mostra a temporada.",text:"Que travessia as tripulações fazem em junho? Onde os barcos passam o inverno? Que mês traz o meltemi, e qual lado da baía é mais protegido dos raios? Respostas que só aparecem quando você olha muitos anos de uma vez."},chapters:[{id:"routes",number:"01",kicker:"Rotas de navegação",title:"Planeje travessias com a experiência de milhares de tripulações.",text:"Milhares de viagens reais mostram quando uma travessia faz sentido, em que sentido, e onde as tripulações partem e chegam. Os ventos predominantes, bons lugares para esperar uma janela de tempo e uma chegada segura depois de uma noite no mar já estão ali. Da Sicília às Ilhas Jônicas, por exemplo, a maioria dos barcos segue para leste em maio e junho e volta em setembro.",points:["Popularidade por mês e sentido","As rotas mais populares na área visível do mapa","Compartilhe uma rota com sua tripulação"],image:"route-detail",alt:"A rota da Sicília às Ilhas Jônicas selecionada, com a popularidade em cada mês e sentido.",coords:"38°12′N · 017°30′E",caption:"Sicília → Ilhas Jônicas, por mês e sentido"},{id:"route-wind",number:"02",kicker:"O vento na rota",title:"Conheça o vento antes de soltar as amarras.",text:"Cada rota mostra o vento que você pode esperar nela, mês a mês: de onde ele vem, com que força sopra, quanto da travessia você navega em orça, de través ou de popa, e com que frequência o mar fica calmo. Da Sicília às Ilhas Jônicas em maio: vento de noroeste, força 3 Beaufort, mais da metade do caminho de popa.",points:["Vento predominante e força Beaufort para cada mês","Orça, través ou popa no rumo da rota","Estado do mar ao longo da rota"],image:"route-wind",alt:"O cartão da rota da Sicília às Ilhas Jônicas: vento predominante, força Beaufort, força do vento, mareação e estado do mar para cada mês, com maio selecionado.",coords:"",caption:"Sicília → Ilhas Jônicas, vento em maio",card:!0},{id:"stays",number:"03",kicker:"Pausas dos barcos",title:"Onde os outros barcos ficam.",text:"Onde as tripulações deixam o barco por dois meses no verão, e onde passam o inverno? As pausas dos barcos mostram os portos e ancoradouros onde barcos ficaram parados — de poucos dias a mais de seis meses, por temporada.",points:["Filtre pela duração da permanência","Veja em que meses os barcos ficam em um lugar","Descubra portos populares para invernar"],image:"stay-detail",alt:"Preveza: permanência típica e os meses em que os barcos ficam ali.",coords:"38°57′N · 020°45′E",caption:"Preveza, permanência e temporada"},{id:"hotspots",number:"04",kicker:"Hotspots",title:"Encontre o ancoradouro mais tranquilo.",text:"Onde os barcos se aglomeram em agosto, e onde ainda há espaço? Hotspots mostra, mês a mês, o movimento de cada área de navegação. O mar Jônico e o golfo Sarônico brilham, enquanto Andros, a um dia de navegação de Atenas, continua tranquila.",points:["De tranquilo a lotado","Todos os meses do ano","Meses mais e menos movimentados em qualquer ponto"],image:"hotspots",alt:"O movimento das áreas de navegação gregas em agosto: lotado em torno das ilhas Jônicas e no golfo Sarônico, tranquilo perto de Andros, com o inspetor de ponto aberto.",coords:"38°24′N · 023°36′E",caption:"Hotspots, Grécia, agosto"},{id:"wind",number:"05",kicker:"Vento",title:"Quanto vento norte esperar?",text:"Escolha uma direção e um mês: em julho, o centro do Egeu fica azul-escuro. É o meltemi. Toque em um ponto perto de Mykonos e você vê o vento soprar do norte em 60% de todas as horas de julho, ou mais.",points:["Intensidade e direção para cada mês","Vento por horário","Toque em qualquer ponto para ver os números"],image:"wind",alt:"Com que frequência o vento sopra do norte no Mar Egeu em julho, com o inspetor de ponto aberto perto de Mykonos.",coords:"37°36′N · 025°00′E",caption:"Vento norte, Mar Egeu, julho"},{id:"waves",number:"06",kicker:"Ondas",title:"Conheça o mar antes de sair.",text:"Quantos dias por mês trazem ondas de 2,5 m ou mais? Em janeiro, o alcance do mistral sobre o Golfo de Leão aparece com clareza.",points:["De mar calmo a muito agitado","Ondulação e mar curto e íngreme","Todos os meses do ano"],image:"waves",alt:"Dias de mar agitado no Mediterrâneo ocidental em janeiro.",coords:"41°00′N · 005°00′E",caption:"Dias agitados, Mediterrâneo ocidental, janeiro"},{id:"potential",number:"07",kicker:"Potencial de tempestades",title:"Onde as tempestades podem se formar.",text:"A parcela do tempo com condições favoráveis a tempestades, mês a mês — inclusive em lugares onde elas poderiam ter se formado em dias em que nenhuma se formou.",points:["Todos os meses do ano","Toque em qualquer ponto para ver os números"],image:"potential",alt:"Potencial de tempestades na região do Panamá em setembro.",coords:"09°00′N · 079°30′W",caption:"Potencial de tempestades, Panamá, setembro"},{id:"terrain",number:"08",kicker:"Exposição do terreno",title:"Mesma baía, outra proteção.",text:"Os morros ao redor podem proteger um ancoradouro dos raios. A exposição do terreno mostra o quanto o relevo protege cada parte de uma baía, para você escolher o lado melhor antes de lançar a âncora.",points:["Compare pontos dentro da mesma baía","Combine com os dias de tempestade históricos"],image:"terrain",alt:"Exposição do terreno na baía de Komiža, em Vis, Croácia.",coords:"43°02′N · 016°05′E",caption:"Baía de Komiža, Vis",markers:[{x:56.9,y:57.69,text:"Pouca proteção do relevo ao redor.",color:"#762a83"},{x:53.84,y:26.35,text:"Alguma proteção do relevo ao redor.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Maior proteção do relevo ao redor.",color:"#5aae61"}]}],story:{kicker:"Nossa história",title:"Nasceu de um susto.",text:"Em outubro de 2024, nossa família velejava no Mar Jônico quando um raio caiu bem ao lado do nosso barco. Aquele momento levantou uma pergunta simples: estamos mais seguros aqui ou do outro lado da baía? O IncusGrid começou como a resposta — e virou um mapa de tudo o que gostaríamos de ter sabido antes daquela temporada.",more:"Leia a história completa (em inglês)",link:`${e}/blog/introducing-incusgrid/`,place:"Igoumenitsa, Grécia",note:"Onde a ideia nasceu"},fromBlog:{kicker:"Do blog",title:"Histórias de dados direto do mar.",all:"Todos os posts",note:"Posts em inglês."},devices:{kicker:"Web & Android",title:"No convés ou na mesa de navegação.",text:"Use o IncusGrid em qualquer navegador ou instale o app para Android. Busque sua área de navegação e explore no celular, no tablet ou no notebook.",points:["Sem instalação no navegador","App para Android no Google Play","Disponível em 19 idiomas"],web:"Abrir no navegador",android:"Baixar no Google Play",phoneAlt:"App do IncusGrid para Android mostrando pausas dos barcos ao redor das Ilhas Jônicas."},final:{title:"Planeje sua próxima temporada.",text:"Rotas, pausas dos barcos, vento, ondas e raios — um só mapa, feito com muitos anos de dados reais.",cta:"Abrir o mapa"},disclaimerLabel:"Atenção",disclaimer:"O IncusGrid mostra padrões históricos para planejamento. Não é previsão do tempo nem auxílio à navegação. As rotas são traçadas de forma esquemática, e as pausas dos barcos são deduzidas de interrupções nos registros de posição, não de vagas confirmadas. Sempre confira as previsões atuais, as cartas náuticas oficiais e as condições locais antes de sair para o mar.",footer:{blog:"Blog",legal:"Aviso legal",privacy:"Política de privacidade",terms:"Termos de uso",cookies:"Configurações de cookies",support:"Suporte",madeWith:"Feito com",made:"em Portugal",englishOnly:"As páginas jurídicas estão em inglês."}},f={path:"/ru",htmlLang:"ru",ogLocale:"ru_RU",meta:{title:"IncusGrid · Планируйте парусный сезон по реальным данным",description:"Парусные маршруты и стоянки судов по реальным переходам, а также многолетние данные о ветре, волнах и молниях на одной карте. Планируйте следующий сезон.",keywords:"парусные маршруты, яхтенные маршруты, планирование яхтенного похода, якорная стоянка, марина, зимовка яхты, статистика ветра, волнение моря, волны, грозы, молнии, мельтеми, яхтинг, парусный туризм, круизный яхтинг"},nav:{routes:"Маршруты",stays:"Стоянки",weather:"Погода",terrain:"Рельеф",blog:"Блог",openApp:"Открыть карту"},hero:{position:"Sailing intelligence",titleA:"Не очередное приложение погоды.",titleB:"Не очередная соцсеть яхтсменов.",lead:"IncusGrid превращает годы данных в местные знания, которые нужны каждому экипажу до отхода: реальные перемещения судов, ветер, волны и молнии на одной карте — чтобы вы планировали следующий переход с коллективными знаниями тысяч яхтсменов.",ctaApp:"Открыть карту",ctaAndroid:"Приложение для Android",heroAlt:"Парусные маршруты в Карибском море — от острова Гаити до Малых Антильских островов и побережья Южной Америки, построенные по реальным переходам крейсерских яхт.",heroCaption:"Парусные маршруты, Карибское море · все месяцы",notes:[{label:"Суда",value:"Тысячи"},{label:"Перемещения",value:"Миллионы"},{label:"Удары молний",value:"Миллиарды"},{label:"Охват",value:"Весь мир"}]},contrast:{kicker:"Не прогноз",title:"Прогноз расскажет о завтрашнем дне. IncusGrid — о целом сезоне.",text:"Каким переходом экипажи идут в июне? Где суда зимуют? В каком месяце дует мельтеми и какая сторона бухты лучше защищена от молний? Такие ответы видны, только когда смотришь сразу на много лет."},chapters:[{id:"routes",number:"01",kicker:"Парусные маршруты",title:"Планируйте переходы на опыте тысяч экипажей.",text:"Тысячи реальных переходов показывают, когда переход имеет смысл, в каком направлении, откуда экипажи выходят и куда приходят. Преобладающие ветры, удобные места, чтобы дождаться погодного окна, и безопасный подход к берегу после ночи в море уже учтены. Например, от Сицилии к Ионическим островам большинство судов идёт на восток в мае и июне, а возвращается в сентябре.",points:["Популярность по месяцам и направлениям","Самые популярные маршруты в текущей области карты","Делитесь маршрутом со своим экипажем"],image:"route-detail",alt:"Выбран маршрут от Сицилии к Ионическим островам: его популярность по месяцам и направлениям.",coords:"38°12′N · 017°30′E",caption:"Сицилия → Ионические острова, по месяцам и направлениям"},{id:"route-wind",number:"02",kicker:"Ветер на маршруте",title:"Знайте ветер до того, как отдать швартовы.",text:"Каждый маршрут показывает, какого ветра на нём ждать, месяц за месяцем: откуда он дует, насколько сильно, какую часть перехода вы идёте в бейдевинд, галфвинд или попутным ветром и как часто море остаётся спокойным. От Сицилии к Ионическим островам в мае: ветер с северо-запада, 3 балла по Бофорту, больше половины пути попутным ветром.",points:["Преобладающий ветер и сила по Бофорту для каждого месяца","Бейдевинд, галфвинд или попутный ветер на курсе маршрута","Состояние моря вдоль маршрута"],image:"route-wind",alt:"Карточка маршрута от Сицилии к Ионическим островам: преобладающий ветер, сила по Бофорту, сила ветра, курс и состояние моря для каждого месяца, выбран май.",coords:"",caption:"Сицилия → Ионические острова, ветер в мае",card:!0},{id:"stays",number:"03",kicker:"Стоянки судов",title:"Где стоят другие суда.",text:"Где экипажи оставляют лодку на два летних месяца и где проводят зиму? Стоянки судов показывают гавани и якорные стоянки, где суда делали паузу, — от нескольких дней до более чем полугода, по сезонам.",points:["Фильтр по длительности стоянки","В какие месяцы суда стоят в этом месте","Популярные гавани для зимовки"],image:"stay-detail",alt:"Превеза: типичная длительность стоянки и месяцы, когда там стоят суда.",coords:"38°57′N · 020°45′E",caption:"Превеза, длительность стоянки и сезон"},{id:"hotspots",number:"04",kicker:"Хотспоты",title:"Найдите стоянку потише.",text:"Где в августе тесно от яхт, а где ещё есть место? Хотспоты показывают по месяцам, насколько оживлён каждый район плавания. Ионическое море и Сароникос светятся, а Андрос, в дне перехода от Афин, остаётся спокойным.",points:["От спокойного до переполненного","Каждый месяц года","Самые оживлённые и самые спокойные месяцы в любой точке"],image:"hotspots",alt:"Насколько оживлены районы плавания Греции в августе: многолюдно у Ионических островов и в заливе Сароникос, спокойно у Андроса, открыт инспектор точки.",coords:"38°24′N · 023°36′E",caption:"Хотспоты, Греция, август"},{id:"wind",number:"05",kicker:"Ветер",title:"Сколько северного ветра ждать?",text:"Выберите направление и месяц: в июле центральная часть Эгейского моря окрашивается в тёмно-синий. Это мельтеми. Нажмите на точку у Миконоса — и увидите, что в июле ветер дует с севера в 60% всех часов или чаще.",points:["Сила и направление для каждого месяца","Ветер по времени суток","Нажмите на точку, чтобы увидеть её значения"],image:"wind",alt:"Как часто в июле в Эгейском море дует ветер с севера; инспектор точки открыт у Миконоса.",coords:"37°36′N · 025°00′E",caption:"Ветер с севера, Эгейское море, июль"},{id:"waves",number:"06",kicker:"Волны",title:"Знайте волнение до выхода в море.",text:"Сколько дней в месяц приносят волны 2,5 м и выше? В январе хорошо видно, как далеко над Лионским заливом достаёт мистраль.",points:["От спокойного до очень неспокойного моря","Зыбь и короткая крутая волна","Каждый месяц года"],image:"waves",alt:"Дни с сильным волнением в западном Средиземноморье в январе.",coords:"41°00′N · 005°00′E",caption:"Дни с сильным волнением, западное Средиземноморье, январь"},{id:"potential",number:"07",kicker:"Грозовой потенциал",title:"Где могут сформироваться грозы.",text:"Доля времени с условиями, благоприятными для гроз, месяц за месяцем — в том числе там, где гроза могла бы сформироваться даже в те дни, когда её не было.",points:["Каждый месяц года","Нажмите на точку, чтобы увидеть её значения"],image:"potential",alt:"Грозовой потенциал в районе Панамы в сентябре.",coords:"09°00′N · 079°30′W",caption:"Грозовой потенциал, Панама, сентябрь"},{id:"terrain",number:"08",kicker:"Открытость рельефа",title:"Одна бухта — разная защита.",text:"Окружающие холмы могут экранировать якорную стоянку от молний. Открытость рельефа показывает, насколько хорошо рельеф защищает каждую часть бухты, — чтобы выбрать лучшую сторону ещё до того, как отдать якорь.",points:["Сравнивайте места в пределах одной бухты","Сочетайте с историческими грозовыми днями"],image:"terrain",alt:"Открытость рельефа в бухте Комижа на острове Вис, Хорватия.",coords:"43°02′N · 016°05′E",caption:"Бухта Комижа, остров Вис",markers:[{x:56.9,y:57.69,text:"Слабое экранирование окружающим рельефом.",color:"#762a83"},{x:53.84,y:26.35,text:"Некоторое экранирование окружающим рельефом.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Более сильное экранирование окружающим рельефом.",color:"#5aae61"}]}],story:{kicker:"Наша история",title:"Всё началось с опасного момента.",text:"В октябре 2024 года наша семья ходила по Ионическому морю, когда молния ударила совсем рядом с нашей лодкой. После этого встал простой вопрос: здесь мы в большей безопасности или на другой стороне бухты? IncusGrid начался как ответ на него — и вырос в карту всего, что нам хотелось бы знать до того сезона.",more:"Читать всю историю (на английском)",link:`${e}/blog/introducing-incusgrid/`,place:"Игуменица, Греция",note:"Где родилась идея"},fromBlog:{kicker:"Из блога",title:"Истории о море в данных.",all:"Все статьи",note:"Статьи на английском."},devices:{kicker:"Веб и Android",title:"На палубе или за штурманским столом.",text:"Пользуйтесь IncusGrid в любом браузере или установите приложение для Android. Найдите свой район плавания и изучайте его на телефоне, планшете или ноутбуке.",points:["В браузере без установки","Приложение для Android в Google Play","Доступно на 19 языках"],web:"Открыть в браузере",android:"Скачать в Google Play",phoneAlt:"Приложение IncusGrid для Android: стоянки судов у Ионических островов."},final:{title:"Спланируйте следующий сезон.",text:"Маршруты, стоянки судов, ветер, волны и молнии — одна карта, построенная на многолетних реальных данных.",cta:"Открыть карту"},disclaimerLabel:"Внимание",disclaimer:"IncusGrid показывает исторические закономерности для планирования. Это не прогноз погоды и не навигационное пособие. Маршруты нарисованы схематично, а стоянки судов выведены из пауз в сообщениях с судов, а не из подтверждённых мест стоянки. Перед выходом в море всегда проверяйте актуальные прогнозы, официальные карты и местные условия.",footer:{blog:"Блог",legal:"Правовая информация",privacy:"Политика конфиденциальности",terms:"Условия использования",cookies:"Настройки cookie",support:"Поддержка",madeWith:"Сделано с",made:"в Португалии",englishOnly:"Юридические страницы — на английском."}},j={path:"/zh-hans",htmlLang:"zh-Hans",ogLocale:"zh_CN",meta:{title:"IncusGrid · 用真实数据规划你的航海季",description:"来自真实航程的航行路线和船舶停留候选地，加上多年的风、浪和雷电数据，尽在一张地图。借助数千名帆船手的集体智慧，规划你的下一个航海季。",keywords:"帆船, 帆船航行, 帆船航线, 巡航, 航海规划, 远洋航行, 锚地, 游艇码头, 帆船过冬, 风况统计, 海况, 海浪, 涌浪, 雷电, 雷暴, 游艇, 地中海帆船"},nav:{routes:"路线",stays:"船舶停留候选地",weather:"天气",terrain:"地形",blog:"博客",openApp:"打开地图"},hero:{position:"Sailing intelligence",titleA:"不是又一个天气应用，",titleB:"也不是又一个帆船社交网络。",lead:"IncusGrid 将多年数据转化为每位船员出航前都需要的本地知识：真实的船只移动、风、浪和雷电尽在一张地图——让你借助数千名帆船手的集体智慧，规划下一段航程。",ctaApp:"打开地图",ctaAndroid:"Android 应用",heroAlt:"加勒比海的航行路线，从伊斯帕尼奥拉岛经小安的列斯群岛延伸到南美洲海岸，根据巡航帆船的真实航程绘制。",heroCaption:"航行路线，加勒比海 · 全部月份",notes:[{label:"船只",value:"数千艘"},{label:"移动",value:"数百万次"},{label:"雷击",value:"数十亿次"},{label:"覆盖范围",value:"全球"}]},contrast:{kicker:"不是天气预报",title:"预报告诉你明天。IncusGrid 告诉你整个季节。",text:"六月，船员们走哪条航线？船只在哪里过冬？梅尔特米风在哪个月到来？海湾的哪一侧更能躲避雷电？这些答案，只有把许多年放在一起看时才会浮现。"},chapters:[{id:"routes",number:"01",kicker:"航行路线",title:"借助数千个船组的经验规划跨海航行。",text:"数千段真实航程告诉你，跨海航行何时合适、朝哪个方向，以及船员从哪里出发、在哪里抵达。盛行风、等待天气窗口的好去处、夜航后安全的登陆点，都已包含其中。比如从西西里岛到爱奥尼亚群岛，大多数船只在五六月向东航行，九月返航。",points:["按月份和方向的热度","当前地图视野内最热门的航线","与船员分享航线"],image:"route-detail",alt:"已选中从西西里岛到爱奥尼亚群岛的航线，显示其按月份和方向的热度。",coords:"38°12′N · 017°30′E",caption:"西西里岛 → 爱奥尼亚群岛，按月份和方向"},{id:"route-wind",number:"02",kicker:"沿途风况",title:"解缆之前，先了解风。",text:"每条航线都按月显示你可以预期的风：从哪里吹来、风力多大、航程中有多少是迎风、横风或顺风航行，以及海面保持平静的频率。比如五月从西西里岛到爱奥尼亚群岛：西北风，蒲福3级，一半以上的航程为顺风。",points:["每月的盛行风和蒲福风级","本航线航向上的迎风、横风或顺风","沿航线的海况"],image:"route-wind",alt:"从西西里岛到爱奥尼亚群岛的航线卡片：每月的盛行风、蒲福风级、风力、航向和海况，已选中五月。",coords:"",caption:"西西里岛 → 爱奥尼亚群岛，五月的风",card:!0},{id:"stays",number:"03",kicker:"船舶停留候选地",title:"其他船停在哪里。",text:"夏天船员们把船留在哪里两个月？冬天又在哪里度过？船舶停留候选地显示船只真正停留在哪里、停留多久：来自数千次真实船只移动的集体智慧。从几天到六个月以上，按季节呈现港口和锚地。",points:["按停留时长筛选","查看船只在哪些月份停留在此","发现热门的过冬港口"],image:"stay-detail",alt:"普雷韦扎：典型停留时长，以及船只停留在此的月份。",coords:"38°57′N · 020°45′E",caption:"普雷韦扎，停留时长与季节"},{id:"hotspots",number:"04",kicker:"热点",title:"找一处更安静的锚地。",text:"八月里哪里船多拥挤，哪里还有空位？热点按月显示每片航行海域的繁忙程度。爱奥尼亚海和萨罗尼科斯湾一片亮色，而距雅典一天航程的安德罗斯岛依然清静。",points:["从清静到拥挤","一年中的每个月","任意地点最繁忙和最清静的月份"],image:"hotspots",alt:"希腊航行海域八月的繁忙程度：爱奥尼亚群岛周边和萨罗尼科斯湾十分拥挤，安德罗斯岛附近清静，地点查看器已打开。",coords:"38°24′N · 023°36′E",caption:"热点，希腊，八月"},{id:"wind",number:"05",kicker:"风",title:"北风会有多少？",text:"选择风向和月份：七月，爱琴海中部变成深蓝色。这就是梅尔特米风。点按米科诺斯岛附近的一个点，你会看到七月里有 60% 甚至更多的时间风从北方吹来。",points:["每个月的风力和风向","按时段查看风况","点按任意地点查看数据"],image:"wind",alt:"七月爱琴海北风出现的频率，米科诺斯岛附近的地点详情已打开。",coords:"37°36′N · 025°00′E",caption:"北风，爱琴海，七月"},{id:"waves",number:"06",kicker:"海浪",title:"出航之前，先知海况。",text:"每个月有多少天浪高达到 2.5 米或以上？一月里，密史脱拉风在利翁湾上的影响范围清晰可见。",points:["从平静到巨浪","涌浪与短而陡的浪","一年中的每个月"],image:"waves",alt:"一月地中海西部的大浪天数。",coords:"41°00′N · 005°00′E",caption:"大浪天数，地中海西部，一月"},{id:"potential",number:"07",kicker:"雷暴潜势",title:"雷暴可能在哪里形成。",text:"逐月显示具备有利雷暴条件的时间占比——即使在当天并未形成雷暴的地方，也能看出雷暴本可能发展的区域。",points:["一年中的每个月","点按任意地点查看数据"],image:"potential",alt:"九月巴拿马周边的雷暴潜势。",coords:"09°00′N · 079°30′W",caption:"雷暴潜势，巴拿马，九月"},{id:"terrain",number:"08",kicker:"地形暴露度",title:"同一个海湾，屏蔽各不相同。",text:"周围的山丘可以帮锚地挡住雷电。地形暴露度显示地形对海湾每个位置的保护程度，让你在下锚前选好更有利的一侧。",points:["比较同一海湾内的不同位置","结合历史雷暴日一起查看"],image:"terrain",alt:"克罗地亚维斯岛科米扎湾的地形暴露度。",coords:"43°02′N · 016°05′E",caption:"维斯岛科米扎湾",markers:[{x:56.9,y:57.69,text:"周围地形的屏蔽作用较弱。",color:"#762a83"},{x:53.84,y:26.35,text:"周围地形有一定的屏蔽作用。",color:"#ecd27a"},{x:35.86,y:27.83,text:"周围地形的屏蔽作用较强。",color:"#5aae61"}]}],story:{kicker:"我们的故事",title:"源于一次惊险时刻。",text:"2024 年 10 月，我们一家在爱奥尼亚海航行时，一道闪电就落在我们的船旁边。那一刻，一个简单的问题摆在眼前：我们待在这里更安全，还是去海湾另一侧更安全？IncusGrid 由此起步，并逐渐成长为一张地图，装下了那个航海季之前我们希望早已知道的一切。",more:"阅读完整故事（英文）",link:`${e}/blog/introducing-incusgrid/`,place:"希腊，伊古迈尼察",note:"想法诞生的地方"},fromBlog:{kicker:"博客",title:"来自海上的数据故事。",all:"全部文章",note:"文章为英文。"},devices:{kicker:"Web & Android",title:"甲板上，或海图桌前。",text:"在任意浏览器中使用 IncusGrid，或安装 Android 应用。搜索你的航行区域，在手机、平板或笔记本电脑上探索。",points:["浏览器中无需安装","Google Play 上的 Android 应用","支持 19 种语言"],web:"在浏览器中打开",android:"在 Google Play 获取",phoneAlt:"IncusGrid Android 应用显示爱奥尼亚群岛周边的船舶停留候选地。"},final:{title:"规划你的下一个航海季。",text:"路线、船舶停留候选地、风、浪和雷电——一张地图，基于多年的真实数据。",cta:"打开地图"},disclaimerLabel:"注意",disclaimer:"IncusGrid 显示用于规划的历史规律，不是天气预报，也不是导航工具。路线为示意绘制，船舶停留候选地由船只位置报告中的中断推断而来，并非确认的泊位。出海前请务必查看最新预报、官方海图和当地情况。",footer:{blog:"博客",legal:"法律声明",privacy:"隐私政策",terms:"服务条款",cookies:"Cookie 设置",support:"支持",madeWith:"在葡萄牙用",made:"打造",englishOnly:"法律页面仅提供英文版。"}},w={path:"/hi",htmlLang:"hi",ogLocale:"hi_IN",meta:{title:"IncusGrid · असली डेटा से अपने नौकायन सीज़न की योजना बनाएँ",description:"असली यात्राओं से बने नौकायन मार्ग और नावों के ठहराव, साथ में वर्षों का हवा, लहरों और बिजली का डेटा, सब एक मानचित्र पर। अपने अगले सीज़न की योजना बनाएँ।",keywords:"नौकायन मार्ग, सेलिंग रूट, नौकायन योजना, यॉट, सेलबोट, लंगरगाह, मरीना, हवा के आँकड़े, समुद्र की स्थिति, लहरें, बिजली, तड़ित-झंझा, आंधी-तूफ़ान, नौकायन, sailing routes, yacht cruising"},nav:{routes:"मार्ग",stays:"ठहराव",weather:"मौसम",terrain:"भूभाग",blog:"ब्लॉग",openApp:"मानचित्र खोलें"},hero:{position:"Sailing intelligence",titleA:"एक और मौसम ऐप नहीं।",titleB:"एक और सेलिंग नेटवर्क नहीं।",lead:"IncusGrid वर्षों के डेटा को वह स्थानीय जानकारी बनाता है जिसकी हर क्रू को रवाना होने से पहले ज़रूरत होती है: असली नाव गतिविधियाँ, हवा, लहरें और बिजली — सब एक मानचित्र पर, ताकि आप हज़ारों नाविकों के सामूहिक ज्ञान से अपनी अगली यात्रा की योजना बना सकें।",ctaApp:"मानचित्र खोलें",ctaAndroid:"Android ऐप",heroAlt:"कैरिबियन सागर में नौकायन मार्ग, हिस्पानियोला से लेसर एंटिलीज़ और दक्षिण अमेरिका के तट तक, क्रूज़िंग नावों की असली यात्राओं से बने।",heroCaption:"नौकायन मार्ग, कैरिबियन सागर · सभी महीने",notes:[{label:"नावें",value:"हज़ारों"},{label:"गतिविधियाँ",value:"लाखों"},{label:"बिजली गिरने की घटनाएँ",value:"अरबों"},{label:"कवरेज",value:"दुनिया भर में"}]},contrast:{kicker:"पूर्वानुमान नहीं",title:"पूर्वानुमान आपको कल के बारे में बताता है। IncusGrid पूरे सीज़न के बारे में।",text:"जून में क्रू कौन-सा मार्ग चुनते हैं? नावें सर्दियाँ कहाँ बिताती हैं? मेल्टेमी किस महीने आती है, और खाड़ी का कौन-सा किनारा बिजली से बेहतर बचा रहता है? ऐसे जवाब तभी दिखते हैं जब आप कई वर्षों को एक साथ देखते हैं।"},chapters:[{id:"routes",number:"01",kicker:"नौकायन मार्ग",title:"हज़ारों क्रू के अनुभव से पारगमन की योजना बनाएँ।",text:"हज़ारों असली यात्राएँ दिखाती हैं कि पारगमन कब समझदारी है, किस दिशा में, और क्रू कहाँ से निकलते हैं और कहाँ पहुँचते हैं। प्रचलित हवाएँ, मौसम की अनुकूल खिड़की का इंतज़ार करने की अच्छी जगहें और समुद्र में एक रात के बाद सुरक्षित तट-आगमन — सब पहले से इसमें शामिल हैं। उदाहरण के लिए, सिसिली से आयोनियन द्वीपों तक ज़्यादातर नावें मई और जून में पूर्व की ओर जाती हैं और सितंबर में लौटती हैं।",points:["हर महीने और दिशा के अनुसार लोकप्रियता","मौजूदा मानचित्र दृश्य के सबसे लोकप्रिय मार्ग","अपनी क्रू के साथ मार्ग साझा करें"],image:"route-detail",alt:"सिसिली से आयोनियन द्वीपों तक का चुना हुआ मार्ग, हर महीने और दिशा में उसकी लोकप्रियता के साथ।",coords:"38°12′N · 017°30′E",caption:"सिसिली → आयोनियन द्वीप, महीने और दिशा के अनुसार"},{id:"route-wind",number:"02",kicker:"मार्ग पर हवा",title:"रवाना होने से पहले हवा को जानें।",text:"हर मार्ग महीने-दर-महीने दिखाता है कि उस पर कैसी हवा की उम्मीद करें: वह कहाँ से आती है, कितनी तेज़ बहती है, यात्रा का कितना हिस्सा आप हवा के विरुद्ध, आड़ी हवा में या हवा के साथ तय करते हैं, और समुद्र कितनी बार शांत रहता है। मई में सिसिली से आयोनियन द्वीपों तक: उत्तर-पश्चिम से हवा, ब्यूफ़ोर्ट 3, आधे से ज़्यादा रास्ता हवा के साथ।",points:["हर महीने की प्रचलित हवा और ब्यूफ़ोर्ट बल","मार्ग के कोर्स पर हवा के विरुद्ध, आड़ी हवा या हवा के साथ","मार्ग पर समुद्र की स्थिति"],image:"route-wind",alt:"सिसिली से आयोनियन द्वीपों तक का मार्ग कार्ड: हर महीने की प्रचलित हवा, ब्यूफ़ोर्ट बल, हवा की तीव्रता, कोर्स और समुद्र की स्थिति, मई चुना हुआ।",coords:"",caption:"सिसिली → आयोनियन द्वीप, मई में हवा",card:!0},{id:"stays",number:"03",kicker:"नावों के ठहराव",title:"दूसरी नावें कहाँ ठहरती हैं।",text:"गर्मियों में क्रू अपनी नाव दो महीने के लिए कहाँ छोड़ते हैं, और सर्दियाँ कहाँ बिताते हैं? नावों के ठहराव वे बंदरगाह और लंगरगाह दिखाते हैं जहाँ नावें रुकीं — कुछ दिनों से लेकर छह महीने से ज़्यादा तक, सीज़न के अनुसार।",points:["ठहराव की अवधि से फ़िल्टर करें","देखें कि किन महीनों में नावें किसी जगह ठहरती हैं","सर्दियाँ बिताने के लोकप्रिय बंदरगाह खोजें"],image:"stay-detail",alt:"प्रेवेज़ा: ठहराव की आम अवधि और वे महीने जिनमें नावें वहाँ ठहरती हैं।",coords:"38°57′N · 020°45′E",caption:"प्रेवेज़ा, ठहराव की अवधि और सीज़न"},{id:"hotspots",number:"04",kicker:"हॉटस्पॉट",title:"ज़्यादा शांत लंगरगाह खोजें।",text:"अगस्त में नावें कहाँ भीड़ लगाती हैं, और कहाँ अब भी जगह है? हॉटस्पॉट हर महीने दिखाता है कि हर नौकायन क्षेत्र कितना व्यस्त है। आयोनियन सागर और सारोनिक खाड़ी चमकते हैं, जबकि एथेंस से एक दिन की नौकायन दूरी पर एंड्रोस शांत रहता है।",points:["शांत से भीड़भाड़ तक","साल का हर महीना","किसी भी बिंदु पर सबसे व्यस्त और सबसे शांत महीने"],image:"hotspots",alt:"अगस्त में यूनानी नौकायन क्षेत्र कितने व्यस्त हैं: आयोनियन द्वीपों के आसपास और सारोनिक खाड़ी में भीड़, एंड्रोस के पास शांति, पॉइंट इंस्पेक्टर खुला हुआ।",coords:"38°24′N · 023°36′E",caption:"हॉटस्पॉट, यूनान, अगस्त"},{id:"wind",number:"05",kicker:"हवा",title:"उत्तरी हवा कितनी मिलेगी?",text:"दिशा और महीना चुनें: जुलाई में मध्य एजियन सागर गहरा नीला हो जाता है। यही मेल्टेमी है। मायकोनोस के पास किसी बिंदु पर टैप करें, और आप देखेंगे कि जुलाई के 60% या उससे अधिक घंटों में हवा उत्तर से चलती है।",points:["हर महीने की ताकत और दिशा","दिन के समय के अनुसार हवा","किसी भी बिंदु के आँकड़े देखने के लिए टैप करें"],image:"wind",alt:"जुलाई में एजियन सागर में हवा कितनी बार उत्तर से चलती है, मायकोनोस के पास बिंदु-निरीक्षक खुला हुआ।",coords:"37°36′N · 025°00′E",caption:"उत्तर से हवा, एजियन सागर, जुलाई"},{id:"waves",number:"06",kicker:"लहरें",title:"निकलने से पहले समुद्र की स्थिति जानें।",text:"महीने में कितने दिन 2.5 m या उससे ऊँची लहरें आती हैं? जनवरी में लायन की खाड़ी के पार मिस्ट्रल की पहुँच साफ़ दिखती है।",points:["शांत से लेकर बहुत उग्र समुद्र तक","स्वेल और छोटी, खड़ी लहरें","साल का हर महीना"],image:"waves",alt:"जनवरी में पश्चिमी भूमध्य सागर में उग्र समुद्र वाले दिन।",coords:"41°00′N · 005°00′E",caption:"उग्र दिन, पश्चिमी भूमध्य सागर, जनवरी"},{id:"potential",number:"07",kicker:"तड़ित-झंझा की संभावना",title:"जहाँ तड़ित-झंझा बन सकते हैं।",text:"तड़ित-झंझा के अनुकूल परिस्थितियों वाले समय का हिस्सा, महीने-दर-महीने — उन जगहों पर भी जहाँ उन दिनों भी तूफ़ान बन सकता था जब कोई नहीं बना।",points:["साल का हर महीना","किसी भी बिंदु के आँकड़े देखने के लिए टैप करें"],image:"potential",alt:"सितंबर में पनामा के आसपास तड़ित-झंझा की संभावना।",coords:"09°00′N · 079°30′W",caption:"तड़ित-झंझा की संभावना, पनामा, सितंबर"},{id:"terrain",number:"08",kicker:"भूभाग जोखिम",title:"एक ही खाड़ी, अलग-अलग आड़।",text:"आसपास की पहाड़ियाँ किसी लंगरगाह को बिजली से आड़ दे सकती हैं। भूभाग जोखिम दिखाता है कि भूभाग खाड़ी के हर हिस्से को कितनी अच्छी तरह बचाता है, ताकि लंगर डालने से पहले आप बेहतर किनारा चुन सकें।",points:["एक ही खाड़ी के भीतर जगहों की तुलना करें","इसे ऐतिहासिक तड़ित-झंझा वाले दिनों के साथ मिलाकर देखें"],image:"terrain",alt:"क्रोएशिया के विस द्वीप पर कोमिज़ा खाड़ी में भूभाग जोखिम।",coords:"43°02′N · 016°05′E",caption:"कोमिज़ा खाड़ी, विस",markers:[{x:56.9,y:57.69,text:"आसपास के भूभाग से कम आड़।",color:"#762a83"},{x:53.84,y:26.35,text:"आसपास के भूभाग से कुछ आड़।",color:"#ecd27a"},{x:35.86,y:27.83,text:"आसपास के भूभाग से अधिक आड़।",color:"#5aae61"}]}],story:{kicker:"हमारी कहानी",title:"बाल-बाल बचने से जन्मा।",text:"अक्टूबर 2024 में हमारा परिवार आयोनियन सागर में नौकायन कर रहा था, जब हमारी नाव के ठीक बगल में बिजली गिरी। उस पल ने एक सीधा-सा सवाल खड़ा किया: क्या हम यहाँ ज़्यादा सुरक्षित हैं, या खाड़ी के दूसरी ओर? IncusGrid उसी सवाल के जवाब के रूप में शुरू हुआ — और बढ़कर एक ऐसा मानचित्र बन गया जिसमें वह सब है जो काश हमें उस सीज़न से पहले पता होता।",more:"पूरी कहानी पढ़ें (अंग्रेज़ी में)",link:`${e}/blog/introducing-incusgrid/`,place:"इगूमेनित्सा, ग्रीस",note:"जहाँ यह विचार जन्मा"},fromBlog:{kicker:"ब्लॉग से",title:"पानी से जुड़ी डेटा कहानियाँ।",all:"सभी लेख",note:"लेख अंग्रेज़ी में हैं।"},devices:{kicker:"वेब और Android",title:"डेक पर हों या चार्ट टेबल पर।",text:"IncusGrid को किसी भी ब्राउज़र में इस्तेमाल करें या Android ऐप इंस्टॉल करें। अपना नौकायन क्षेत्र खोजें और फ़ोन, टैबलेट या लैपटॉप पर उसे जानें-परखें।",points:["ब्राउज़र में इंस्टॉल करने की ज़रूरत नहीं","Google Play पर Android ऐप","19 भाषाओं में उपलब्ध"],web:"ब्राउज़र में खोलें",android:"Google Play पर पाएँ",phoneAlt:"IncusGrid का Android ऐप, आयोनियन द्वीपों के आसपास नावों के ठहराव दिखाते हुए।"},final:{title:"अपने अगले सीज़न की योजना बनाएँ।",text:"मार्ग, नावों के ठहराव, हवा, लहरें और बिजली — एक मानचित्र, कई वर्षों के असली डेटा से बना।",cta:"मानचित्र खोलें"},disclaimerLabel:"सावधानी",disclaimer:"IncusGrid योजना बनाने के लिए ऐतिहासिक पैटर्न दिखाता है। यह मौसम का पूर्वानुमान या नौवहन सहायक नहीं है। मार्ग सांकेतिक रूप से बनाए गए हैं, और नावों के ठहराव नावों की रिपोर्टों में आए अंतरालों से निकाले जाते हैं, पुष्ट बर्थ से नहीं। समुद्र में जाने से पहले हमेशा ताज़ा पूर्वानुमान, आधिकारिक समुद्री चार्ट और स्थानीय परिस्थितियाँ जाँचें।",footer:{blog:"ब्लॉग",legal:"कानूनी सूचना",privacy:"गोपनीयता नीति",terms:"सेवा की शर्तें",cookies:"कुकी सेटिंग्स",support:"सहायता",madeWith:"पुर्तगाल में",made:"से बनाया गया",englishOnly:"कानूनी पेज अंग्रेज़ी में हैं।"}},z={path:"/ja",htmlLang:"ja",ogLocale:"ja_JP",meta:{title:"IncusGrid · 実データでセーリングシーズンを計画",description:"実際の航海から導いた航行ルートと船の滞在候補、そして長年の風・波・雷のデータをひとつの地図に。数千のセーラーの集合知で、次のシーズンを計画しましょう。",keywords:"セーリング, ヨット, クルージング, 航海計画, 航行ルート, 外洋航海, 錨泊地, マリーナ, 越冬, 上架, 風統計, 海況, 波, うねり, 雷, 雷雨, ヨット 地中海, ロングクルーズ"},nav:{routes:"ルート",stays:"船の滞在候補",weather:"気象",terrain:"地形",blog:"ブログ",openApp:"地図を開く"},hero:{position:"Sailing intelligence",titleA:"よくある天気アプリでも、",titleB:"セーラー向けSNSでもありません。",lead:"IncusGrid は長年のデータを、出航前にどのクルーにも欠かせない現地の知識に変えます。実際の船の動き、風、波、雷をひとつの地図に。数千のセーラーの集合知で、次の航海を計画できます。",ctaApp:"地図を開く",ctaAndroid:"Android アプリ",heroAlt:"イスパニョーラ島から小アンティル諸島、南米沿岸へと続くカリブ海の航行ルート。クルージング艇の実際の航海から描かれています。",heroCaption:"航行ルート、カリブ海 · 全月",notes:[{label:"船",value:"数千隻"},{label:"移動",value:"数百万件"},{label:"落雷",value:"数十億回"},{label:"対象範囲",value:"全世界"}]},contrast:{kicker:"予報ではありません",title:"予報が教えてくれるのは明日のこと。IncusGrid が見せるのはシーズンです。",text:"6月、クルーはどの航路をとるのか。船はどこで冬を越すのか。メルテミが吹くのは何月か。湾のどちら側が雷から守られやすいのか。何年分ものデータを重ねて初めて見えてくる答えです。"},chapters:[{id:"routes",number:"01",kicker:"航行ルート",title:"数千のクルーの経験で横断を計画。",text:"数千の実際の航海から、いつ横断するのが理にかなうか、どの方向か、クルーがどこを出てどこに着くかがわかります。卓越風、ウェザーウィンドウを待つのに適した場所、夜間航海のあとの安全なランドフォールも、すでにそこに織り込まれています。たとえばシチリア島からイオニア諸島へは、多くの船が5月と6月に東へ向かい、9月に戻ってきます。",points:["月別・方向別の人気度","表示中の地図範囲で人気のルート","ルートをクルーと共有"],image:"route-detail",alt:"シチリア島からイオニア諸島へのルートを選択し、月別・方向別の人気度を表示した画面。",coords:"38°12′N · 017°30′E",caption:"シチリア島 → イオニア諸島、月別・方向別"},{id:"route-wind",number:"02",kicker:"ルート上の風",title:"出航前に風を知る。",text:"どのルートでも、予想される風が月ごとにわかります。どこから吹くか、どれくらい強いか、航程のうち風上・横風・追い風で走る割合、そして海が穏やかな頻度まで。たとえば5月のシチリア島からイオニア諸島へは、北西の風、ビューフォート風力3、航程の半分以上が追い風です。",points:["毎月の卓越風とビューフォート風力","ルートの針路に対する風上・横風・追い風","ルート沿いの海況"],image:"route-wind",alt:"シチリア島からイオニア諸島へのルートカード：毎月の卓越風、ビューフォート風力、風の強さ、コース、海況。5月を選択中。",coords:"",caption:"シチリア島 → イオニア諸島、5月の風",card:!0},{id:"stays",number:"03",kicker:"船の滞在候補",title:"ほかの船はどこに泊まるのか。",text:"夏の2か月、クルーはどこに船を置いていくのか。冬はどこで過ごすのか。船の滞在候補は、船が実際にどこに、どれくらい滞在するかを示します。数千の実際の船の動きから生まれた集合知です。数日から6か月以上まで、港や錨泊地での滞在をシーズンごとに表示します。",points:["滞在期間で絞り込み","その場所に船が滞在する月がわかる","人気の越冬港を見つける"],image:"stay-detail",alt:"プレヴェザ：一般的な滞在期間と、船が滞在する月。",coords:"38°57′N · 020°45′E",caption:"プレヴェザ、滞在期間とシーズン"},{id:"hotspots",number:"04",kicker:"ホットスポット",title:"静かな錨地を見つけよう。",text:"8月、ボートが混み合うのはどこで、まだ空いているのはどこか。ホットスポットは、各セーリングエリアの混み具合を月ごとに示します。イオニア海とサロニコス湾が明るく光る一方、アテネから1日の航程にあるアンドロス島は静かなままです。",points:["静かな場所から混雑した場所まで","1年のすべての月","どの地点でも最も混む月と空いている月"],image:"hotspots",alt:"8月のギリシャのセーリングエリアの混み具合：イオニア諸島周辺とサロニコス湾は混雑、アンドロス島沖は静か。地点インスペクターを表示中。",coords:"38°24′N · 023°36′E",caption:"ホットスポット、ギリシャ、8月"},{id:"wind",number:"05",kicker:"風",title:"北風はどれくらい吹くのか。",text:"風向と月を選ぶと、7月のエーゲ海中央部が濃い青に染まります。これがメルテミです。ミコノス島付近の地点をタップすると、7月の全時間の60％以上で北から吹いていることがわかります。",points:["毎月の風の強さと風向","時間帯別の風","地点をタップして数値を確認"],image:"wind",alt:"7月のエーゲ海で北風が吹く頻度。ミコノス島付近で地点の詳細を開いた画面。",coords:"37°36′N · 025°00′E",caption:"北からの風、エーゲ海、7月"},{id:"waves",number:"06",kicker:"波",title:"出航前に海況を知る。",text:"波高2.5 m以上の日は月に何日あるのか。1月には、ミストラルがリオン湾の沖までどこまで届くかがはっきり見えます。",points:["穏やかな海から非常に荒れた海まで","うねりと短く急な波","1年のすべての月"],image:"waves",alt:"1月の西地中海で海が荒れた日。",coords:"41°00′N · 005°00′E",caption:"荒れた日、西地中海、1月"},{id:"potential",number:"07",kicker:"雷雨の発生ポテンシャル",title:"雷雨が発達しうる場所。",text:"雷雨が起きやすい条件だった時間の割合を、月ごとに表示します。実際には雷雨が発生しなかった日でも、発達しえた場所まで含めて。",points:["1年のすべての月","地点をタップして数値を確認"],image:"potential",alt:"9月のパナマ周辺における雷雨の発生ポテンシャル。",coords:"09°00′N · 079°30′W",caption:"雷雨の発生ポテンシャル、パナマ、9月"},{id:"terrain",number:"08",kicker:"地形による曝露度",title:"同じ湾でも、守られ方は違う。",text:"周囲の丘が、錨泊地を雷から守ってくれることがあります。地形による曝露度は、湾のそれぞれの場所が地形にどれだけ守られているかを示します。錨を下ろす前に、より良い側を選べます。",points:["ひとつの湾の中で場所を比較","過去の雷雨日と組み合わせて"],image:"terrain",alt:"クロアチア、ヴィス島のコミジャ湾における地形による曝露度。",coords:"43°02′N · 016°05′E",caption:"ヴィス島、コミジャ湾",markers:[{x:56.9,y:57.69,text:"周辺地形による遮蔽が少ない場所。",color:"#762a83"},{x:53.84,y:26.35,text:"周辺地形による遮蔽がある程度ある場所。",color:"#ecd27a"},{x:35.86,y:27.83,text:"周辺地形による遮蔽がより大きい場所。",color:"#5aae61"}]}],story:{kicker:"私たちのストーリー",title:"ひやりとした瞬間から生まれました。",text:"2024年10月、家族でイオニア海を航海していたとき、すぐそばに雷が落ちました。そのとき浮かんだのは、ひとつの素朴な疑問です。ここにいる方が安全なのか、それとも湾の反対側の方がいいのか。IncusGrid はその答えとして始まり、あのシーズンの前に知っておきたかったことすべてを載せた地図へと育ちました。",more:"ストーリーを読む（英語）",link:`${e}/blog/introducing-incusgrid/`,place:"ギリシャ、イグメニツァ",note:"アイデアが生まれた場所"},fromBlog:{kicker:"ブログから",title:"海のデータストーリー。",all:"すべての記事",note:"記事は英語です。"},devices:{kicker:"Web & Android",title:"デッキでも、チャートテーブルでも。",text:"IncusGrid はどのブラウザでも使え、Android アプリも用意しています。航行エリアを検索して、スマートフォン、タブレット、ノートパソコンで探索しましょう。",points:["ブラウザならインストール不要","Google Play で Android アプリを提供","19言語に対応"],web:"ブラウザで開く",android:"Google Play で手に入れよう",phoneAlt:"イオニア諸島周辺の船の滞在候補を表示した IncusGrid の Android アプリ。"},final:{title:"次のシーズンを計画しよう。",text:"ルート、船の滞在候補、風、波、雷。長年の実データから作った、ひとつの地図です。",cta:"地図を開く"},disclaimerLabel:"ご注意",disclaimer:"IncusGrid は計画のための過去の傾向を示すものです。天気予報でも航海計器でもありません。ルートは模式的に描かれており、船の滞在候補は船の位置報告の中断から推定したもので、確認済みの係留場所ではありません。出航前には必ず最新の予報、公式の海図、現地の状況を確認してください。",footer:{blog:"ブログ",legal:"運営者情報",privacy:"プライバシーポリシー",terms:"利用規約",cookies:"Cookie 設定",support:"サポート",madeWith:"ポルトガルより",made:"を込めて",englishOnly:"法的ページは英語のみです。"}},x={path:"/ar",htmlLang:"ar",ogLocale:"ar_AR",meta:{title:"IncusGrid · خطّط لموسم الإبحار ببيانات حقيقية",description:"مسارات إبحار وتوقفات قوارب مستمدة من رحلات حقيقية، إلى جانب سنوات من بيانات الرياح والأمواج والبرق على خريطة واحدة. خطّط لموسمك القادم.",keywords:"مسارات الإبحار، الإبحار الشراعي، رحلات اليخوت، تخطيط رحلة بحرية، مرسى، مارينا، إحصاءات الرياح، حالة البحر، الأمواج، البرق، العواصف الرعدية، يخت، قارب شراعي، البحر المتوسط"},nav:{routes:"المسارات",stays:"توقفات القوارب",weather:"الطقس",terrain:"التضاريس",blog:"المدونة",openApp:"افتح الخريطة"},hero:{position:"Sailing intelligence",titleA:"ليس تطبيق طقس آخر.",titleB:"وليس شبكة بحّارة أخرى.",lead:"يحوّل IncusGrid سنوات من البيانات إلى المعرفة المحلية التي يحتاجها كل طاقم قبل الإبحار: تحركات حقيقية للقوارب، والرياح والأمواج والبرق على خريطة واحدة — لتخطّط لعبورك القادم بالمعرفة الجماعية لآلاف البحّارة.",ctaApp:"افتح الخريطة",ctaAndroid:"تطبيق Android",heroAlt:"مسارات الإبحار عبر البحر الكاريبي، من هيسبانيولا إلى جزر الأنتيل الصغرى وساحل أمريكا الجنوبية، مرسومة من رحلات حقيقية لقوارب الإبحار.",heroCaption:"مسارات الإبحار، البحر الكاريبي · كل الأشهر",notes:[{label:"القوارب",value:"الآلاف"},{label:"التحركات",value:"الملايين"},{label:"ضربات البرق",value:"المليارات"},{label:"التغطية",value:"حول العالم"}]},contrast:{kicker:"ليست توقعات جوية",title:"التوقعات تخبرك عن الغد. أما IncusGrid فيخبرك عن الموسم كله.",text:"أي عبور تسلكه الطواقم في يونيو؟ أين تقضي القوارب الشتاء؟ أي شهر يجلب رياح الميلتمي، وأي جانب من الخليج أفضل حماية من البرق؟ إجابات لا تظهر إلا حين تنظر إلى سنوات كثيرة دفعة واحدة."},chapters:[{id:"routes",number:"01",kicker:"مسارات الإبحار",title:"خطّط لعبورك بخبرة آلاف الطواقم.",text:"تُظهر آلاف الرحلات الحقيقية متى يكون العبور منطقيًا، وفي أي اتجاه، ومن أين تنطلق الطواقم وإلى أين تصل. الرياح السائدة، والأماكن المناسبة لانتظار نافذة طقس، والوصول الآمن إلى البر بعد ليلة في البحر، كلها محسوبة سلفًا. فمن صقلية إلى الجزر الأيونية مثلًا، تتجه معظم القوارب شرقًا في مايو ويونيو وتعود في سبتمبر.",points:["الشعبية حسب الشهر والاتجاه","المسارات الأكثر شعبية في عرض الخريطة الحالي","شارك مسارًا مع طاقمك"],image:"route-detail",alt:"المسار من صقلية إلى الجزر الأيونية محددًا، مع مدى شعبيته في كل شهر واتجاه.",coords:"38°12′N · 017°30′E",caption:"صقلية ← الجزر الأيونية، حسب الشهر والاتجاه"},{id:"route-wind",number:"02",kicker:"الرياح على المسار",title:"اعرف الرياح قبل أن تُبحر.",text:"يُظهر كل مسار الرياح التي يمكنك توقعها عليه، شهرًا بشهر: من أين تهب، وما قوتها، وكم من العبور تبحر فيه عكس الريح أو بريح جانبية أو مع الريح، وكم مرة يبقى البحر هادئًا. من صقلية إلى الجزر الأيونية في مايو: رياح شمالية غربية بقوة 3 بوفورت، وأكثر من نصف الطريق مع الريح.",points:["الرياح السائدة وقوتها بمقياس بوفورت لكل شهر","عكس الريح أو بريح جانبية أو مع الريح على مسار الطريق","حالة البحر على طول المسار"],image:"route-wind",alt:"بطاقة المسار من صقلية إلى الجزر الأيونية: الرياح السائدة، وقوة بوفورت، وشدة الرياح، والمسار، وحالة البحر لكل شهر، مع تحديد مايو.",coords:"",caption:"صقلية ← الجزر الأيونية، الرياح في مايو",card:!0},{id:"stays",number:"03",kicker:"توقفات القوارب",title:"أين تبقى القوارب الأخرى.",text:"أين تترك الطواقم قواربها شهرين في الصيف، وأين تقضي الشتاء؟ تُظهر توقفات القوارب الموانئ والمراسي التي توقفت فيها القوارب — من بضعة أيام إلى أكثر من ستة أشهر، حسب الموسم.",points:["التصفية حسب مدة التوقف","اعرف في أي الأشهر تبقى القوارب في مكان ما","اكتشف الموانئ المفضلة لقضاء الشتاء"],image:"stay-detail",alt:"بريفيزا: مدة التوقف المعتادة والأشهر التي تبقى فيها القوارب هناك.",coords:"38°57′N · 020°45′E",caption:"بريفيزا، مدة التوقف والموسم"},{id:"hotspots",number:"04",kicker:"النقاط الساخنة",title:"اعثر على مرسى أهدأ.",text:"أين تزدحم القوارب في أغسطس، وأين لا يزال هناك متسع؟ تُظهر النقاط الساخنة شهرًا بشهر مدى ازدحام كل منطقة إبحار. يتوهج البحر الأيوني وخليج سارونيك، بينما تبقى أندروس، على بُعد يوم إبحار من أثينا، هادئة.",points:["من الهادئ إلى المزدحم","كل شهر من السنة","أكثر الأشهر ازدحامًا وأهدؤها في أي نقطة"],image:"hotspots",alt:"مدى ازدحام مناطق الإبحار اليونانية في أغسطس: مزدحمة حول الجزر الأيونية وفي خليج سارونيك، هادئة قبالة أندروس، مع فتح مستكشف النقطة.",coords:"38°24′N · 023°36′E",caption:"النقاط الساخنة، اليونان، أغسطس"},{id:"wind",number:"05",kicker:"الرياح",title:"كم من الرياح الشمالية تتوقع؟",text:"اختر اتجاهًا وشهرًا: في يوليو يتحول وسط بحر إيجه إلى أزرق داكن. إنها رياح الميلتمي. اضغط على نقطة قرب ميكونوس لترى أنها تهب من الشمال في 60% من ساعات يوليو أو أكثر.",points:["القوة والاتجاه لكل شهر","الرياح حسب وقت اليوم","اضغط على أي نقطة لترى أرقامها"],image:"wind",alt:"كم مرة تهب الرياح من الشمال في بحر إيجه في يوليو، مع فاحص النقطة مفتوحًا قرب ميكونوس.",coords:"37°36′N · 025°00′E",caption:"رياح من الشمال، بحر إيجه، يوليو"},{id:"waves",number:"06",kicker:"الأمواج",title:"اعرف حالة البحر قبل أن تبحر.",text:"كم يومًا في الشهر تبلغ فيه الأمواج 2.5 م أو أكثر؟ في يناير يظهر بوضوح مدى امتداد رياح الميسترال عبر خليج ليون.",points:["من البحر الهادئ إلى شديد الهيجان","الأمواج المتضخمة والموج القصير الحاد","كل شهر من السنة"],image:"waves",alt:"الأيام الهائجة في غرب البحر المتوسط في يناير.",coords:"41°00′N · 005°00′E",caption:"أيام هائجة، غرب البحر المتوسط، يناير"},{id:"potential",number:"07",kicker:"احتمالية العواصف الرعدية",title:"حيث يمكن أن تتشكل العواصف الرعدية.",text:"نسبة الوقت مع ظروف مواتية للعواصف الرعدية، شهرًا بشهر — بما في ذلك أماكن كان يمكن أن تتشكل فيها العواصف حتى في أيام لم تتشكل فيها.",points:["كل شهر من السنة","اضغط على أي نقطة لترى أرقامها"],image:"potential",alt:"احتمالية العواصف الرعدية حول بنما في سبتمبر.",coords:"09°00′N · 079°30′W",caption:"احتمالية العواصف الرعدية، بنما، سبتمبر"},{id:"terrain",number:"08",kicker:"التعرض بحسب التضاريس",title:"الخليج نفسه، وحماية مختلفة.",text:"قد تحجب التلال المحيطة المرسى عن البرق. يُظهر التعرض بحسب التضاريس مدى حماية التضاريس لكل جزء من الخليج، لتختار الجانب الأفضل قبل أن تُلقي المرساة.",points:["قارن بين المواقع داخل خليج واحد","اجمعه مع أيام العواصف الرعدية التاريخية"],image:"terrain",alt:"التعرض بحسب التضاريس في خليج كوميجا بجزيرة فيس، كرواتيا.",coords:"43°02′N · 016°05′E",caption:"خليج كوميجا، جزيرة فيس",markers:[{x:56.9,y:57.69,text:"حجب قليل بفعل التضاريس المحيطة.",color:"#762a83"},{x:53.84,y:26.35,text:"بعض الحجب بفعل التضاريس المحيطة.",color:"#ecd27a"},{x:35.86,y:27.83,text:"حجب أكبر بفعل التضاريس المحيطة.",color:"#5aae61"}]}],story:{kicker:"قصتنا",title:"وُلدت من لحظة خطر.",text:"في أكتوبر 2024 كانت عائلتنا تبحر في البحر الأيوني حين ضرب البرق بجوار قاربنا مباشرة. طرحت تلك اللحظة سؤالًا بسيطًا: هل نحن أكثر أمانًا هنا، أم على الجانب الآخر من الخليج؟ بدأ IncusGrid إجابةً عن هذا السؤال — ثم نما ليصبح خريطة لكل ما تمنّينا لو عرفناه قبل ذلك الموسم.",more:"اقرأ القصة كاملة (بالإنجليزية)",link:`${e}/blog/introducing-incusgrid/`,place:"إيغومينيتسا، اليونان",note:"حيث وُلدت الفكرة"},fromBlog:{kicker:"من المدونة",title:"قصص من البيانات عن البحر.",all:"كل المقالات",note:"المقالات باللغة الإنجليزية."},devices:{kicker:"الويب و Android",title:"على سطح القارب أو عند طاولة الخرائط.",text:"استخدم IncusGrid في أي متصفح أو ثبّت تطبيق Android. ابحث عن منطقة إبحارك واستكشفها على الهاتف أو الجهاز اللوحي أو الحاسوب المحمول.",points:["دون تثبيت في المتصفح","تطبيق Android على Google Play","متاح بـ 19 لغة"],web:"افتح في المتصفح",android:"نزّله من Google Play",phoneAlt:"تطبيق IncusGrid على Android يعرض توقفات القوارب حول الجزر الأيونية."},final:{title:"خطّط لموسمك القادم.",text:"المسارات وتوقفات القوارب والرياح والأمواج والبرق — خريطة واحدة مبنية على سنوات طويلة من البيانات الحقيقية.",cta:"افتح الخريطة"},disclaimerLabel:"تنبيه",disclaimer:"يعرض IncusGrid أنماطًا تاريخية للتخطيط. إنه ليس توقعات للطقس ولا أداة ملاحة. المسارات مرسومة بشكل تخطيطي، وتوقفات القوارب مستنتجة من فترات انقطاع بلاغات القوارب، لا من مراسٍ مؤكدة. تحقق دائمًا من أحدث التوقعات والخرائط البحرية الرسمية والظروف المحلية قبل الإبحار.",footer:{blog:"المدونة",legal:"الإشعار القانوني",privacy:"سياسة الخصوصية",terms:"شروط الخدمة",cookies:"إعدادات ملفات تعريف الارتباط",support:"الدعم",madeWith:"صُنع بـ",made:"في البرتغال",englishOnly:"الصفحات القانونية باللغة الإنجليزية."}},A=[{id:"en",name:"English"},{id:"de",name:"Deutsch"},{id:"fr",name:"Français"},{id:"it",name:"Italiano"},{id:"nl",name:"Nederlands"},{id:"es",name:"Español"},{id:"sv",name:"Svenska"},{id:"da",name:"Dansk"},{id:"nb",name:"Norsk (bokmål)"},{id:"fi",name:"Suomi"},{id:"el",name:"Ελληνικά"},{id:"hr",name:"Hrvatski"},{id:"tr",name:"Türkçe"},{id:"pt-BR",name:"Português (Brasil)"},{id:"ru",name:"Русский"},{id:"zh-Hans",name:"简体中文"},{id:"hi",name:"हिन्दी"},{id:"ja",name:"日本語"},{id:"ar",name:"العربية"}],B={en:o,de:s,fr:l,it:d,nl:u,es:m,sv:c,da:p,nb:g,fi:k,el:v,hr:h,tr:b,"pt-BR":y,ru:f,"zh-Hans":j,hi:w,ja:z,ar:x},E=a=>a==="en"?"/":"/"+a.toLowerCase();function N(a){var i,t;const r=(i=a.replace(/^\/pricing-preview/,"").split("/")[1])==null?void 0:i.toLowerCase();return((t=A.find(n=>n.id!=="en"&&n.id.toLowerCase()===r))==null?void 0:t.id)??"en"}export{S as A,e as B,G as F,P as I,I as P,N as a,B as c,A as l,E as p};
